INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-12', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 12', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 12);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 1, 'tire', 'lốp xe', 'noun', '[{"en":"We got a flat tire on the way to the airport.","vi":"Chúng tôi bị xẹp lốp xe trên đường ra sân bay."},{"en":"You should check your tires before a long drive.","vi":"Bạn nên kiểm tra lốp xe trước một chuyến đi xa."},{"en":"My dad taught me how to change a tire.","vi":"Bố tôi đã dạy tôi cách thay lốp xe."}]', '[{"phrase":"flat tire"},{"phrase":"change a tire"},{"phrase":"spare tire"},{"phrase":"front tire"}]', 'Anh: tyre · Mỹ: tire', '/ˈtaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tir/tire_/tire__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 2, 'spring', 'mùa xuân; lò xo', 'noun', '[{"en":"The cherry trees on our street bloom every spring.","vi":"Những cây anh đào trên phố nhà tôi nở hoa mỗi mùa xuân."},{"en":"We are planning to move to a new apartment next spring.","vi":"Chúng tôi dự định chuyển đến một căn hộ mới vào mùa xuân tới."},{"en":"One of the springs in this old mattress is broken.","vi":"Một cái lò xo trong tấm nệm cũ này bị gãy."}]', '[{"phrase":"in the spring"},{"phrase":"early spring"},{"phrase":"next spring"},{"phrase":"spring break"}]', NULL, '/sprɪŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spr/sprin/spring__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 3, 'spirit', 'tinh thần; tâm trạng', 'noun', '[{"en":"Our coach says team spirit matters more than talent.","vi":"Huấn luyện viên của chúng tôi nói tinh thần đồng đội quan trọng hơn tài năng."},{"en":"Her kind words really lifted my spirits.","vi":"Những lời tử tế của cô ấy thật sự làm tôi phấn chấn lên."},{"en":"Everyone was in high spirits after hearing the good news.","vi":"Mọi người đều rất phấn khởi sau khi nghe tin vui."}]', '[{"phrase":"team spirit"},{"phrase":"in high spirits"},{"phrase":"lift your spirits"},{"phrase":"community spirit"}]', NULL, '/ˈspɪrɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/spi/spiri/spirit__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 4, 'lunch', 'bữa trưa', 'noun', '[{"en":"Let''s have lunch together at the new restaurant tomorrow.","vi":"Mai chúng ta cùng ăn trưa ở nhà hàng mới nhé."},{"en":"I usually bring my lunch to work to save money.","vi":"Tôi thường mang bữa trưa đi làm để tiết kiệm tiền."},{"en":"She was out for lunch when the manager called.","vi":"Cô ấy đang ra ngoài ăn trưa thì quản lý gọi đến."}]', '[{"phrase":"have lunch"},{"phrase":"lunch break"},{"phrase":"eat lunch"},{"phrase":"pack a lunch"}]', NULL, '/lʌntʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lun/lunch/lunch__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 5, 'actual', 'thực tế; thật sự', 'adjective', '[{"en":"The actual cost was much higher than we expected.","vi":"Chi phí thực tế cao hơn nhiều so với chúng tôi dự tính."},{"en":"The movie is based on actual events.","vi":"Bộ phim dựa trên những sự kiện có thật."},{"en":"We practiced a lot, but the actual test was easier.","vi":"Chúng tôi đã luyện tập nhiều, nhưng bài kiểm tra thật lại dễ hơn."}]', '[{"phrase":"actual cost"},{"phrase":"actual number"},{"phrase":"the actual reason"}]', NULL, '/ˈæktʃuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/actua/actual__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 6, 'pool', 'hồ bơi', 'noun', '[{"en":"The kids spent the whole afternoon in the pool.","vi":"Bọn trẻ ở dưới hồ bơi suốt cả buổi chiều."},{"en":"Our hotel has a large outdoor pool on the roof.","vi":"Khách sạn của chúng tôi có một hồ bơi ngoài trời lớn trên sân thượng."},{"en":"Is the swimming pool open to the public on weekends?","vi":"Hồ bơi có mở cửa cho mọi người vào cuối tuần không?"}]', '[{"phrase":"swimming pool"},{"phrase":"outdoor pool"},{"phrase":"indoor pool"}]', NULL, '/puːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/poo/pool_/pool__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 7, 'battle', 'trận đánh; cuộc đấu tranh', 'noun', '[{"en":"The castle was built near the site of a famous battle.","vi":"Lâu đài được xây gần nơi diễn ra một trận đánh nổi tiếng."},{"en":"Getting my son to eat vegetables is a daily battle.","vi":"Bắt con trai tôi ăn rau là một cuộc chiến mỗi ngày."},{"en":"After a long battle, the town finally saved its old library.","vi":"Sau một cuộc đấu tranh dài, thị trấn cuối cùng đã giữ được thư viện cũ."}]', '[{"phrase":"win a battle"},{"phrase":"long battle"},{"phrase":"losing battle"}]', NULL, '/ˈbætl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bat/battl/battle__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 8, 'tradition', 'truyền thống', 'noun', '[{"en":"It''s a family tradition to eat dinner together on Sundays.","vi":"Cùng nhau ăn tối vào Chủ nhật là một truyền thống của gia đình."},{"en":"The town has a long tradition of making pottery.","vi":"Thị trấn có truyền thống làm gốm lâu đời."},{"en":"Many young people no longer follow the old traditions.","vi":"Nhiều người trẻ không còn theo những truyền thống cũ nữa."}]', '[{"phrase":"family tradition"},{"phrase":"long tradition"},{"phrase":"follow a tradition"}]', NULL, '/trəˈdɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/tradi/tradition__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 9, 'cash', 'tiền mặt', 'noun', '[{"en":"Do you want to pay by card or in cash?","vi":"Bạn muốn trả bằng thẻ hay bằng tiền mặt?"},{"en":"I never carry much cash when I travel.","vi":"Tôi không bao giờ mang nhiều tiền mặt khi đi du lịch."},{"en":"The small shop on the corner only accepts cash.","vi":"Cửa hàng nhỏ ở góc phố chỉ nhận tiền mặt."}]', '[{"phrase":"pay in cash"},{"phrase":"cash payment"},{"phrase":"short of cash"}]', 'không đếm được', '/kæʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cas/cash_/cash__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 10, 'hardly', 'hầu như không', 'adverb', '[{"en":"I could hardly hear him because the music was so loud.","vi":"Tôi hầu như không nghe được anh ấy nói vì nhạc quá to."},{"en":"We have hardly ever seen each other since she moved away.","vi":"Từ khi cô ấy chuyển đi, chúng tôi hầu như chưa bao giờ gặp nhau."},{"en":"There was hardly any food left when we arrived.","vi":"Khi chúng tôi đến thì hầu như chẳng còn chút đồ ăn nào."}]', '[{"phrase":"hardly ever"},{"phrase":"hardly any"},{"phrase":"can hardly"}]', 'hardly (hầu như không) ≠ hard (chăm chỉ, vất vả)', '/ˈhɑːrdli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/har/hardl/hardly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 11, 'award', 'giải thưởng', 'noun', '[{"en":"She won an award for her work with local schools.","vi":"Cô ấy đã giành được một giải thưởng nhờ công việc với các trường học địa phương."},{"en":"The restaurant received an award for its excellent service.","vi":"Nhà hàng đã nhận được giải thưởng nhờ dịch vụ xuất sắc."},{"en":"The awards will be given out at the end of the evening.","vi":"Các giải thưởng sẽ được trao vào cuối buổi tối."}]', '[{"phrase":"win an award"},{"phrase":"receive an award"},{"phrase":"award ceremony"}]', NULL, '/əˈwɔːrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/awa/award/award__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 12, 'coach', 'huấn luyện viên; xe khách', 'noun', '[{"en":"Our basketball coach makes us run before every practice.","vi":"Huấn luyện viên bóng rổ bắt chúng tôi chạy trước mỗi buổi tập."},{"en":"The coach told the players to stay calm.","vi":"Huấn luyện viên bảo các cầu thủ giữ bình tĩnh."},{"en":"We traveled from the airport to the city by coach.","vi":"Chúng tôi đi từ sân bay vào thành phố bằng xe khách."}]', '[{"phrase":"head coach"},{"phrase":"football coach"},{"phrase":"by coach"}]', NULL, '/kəʊtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/coa/coach/coach__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 13, 'experiment', 'thí nghiệm; thử nghiệm', 'noun', '[{"en":"The students did a simple experiment with water and salt.","vi":"Các học sinh làm một thí nghiệm đơn giản với nước và muối."},{"en":"The results of the experiment surprised the scientists.","vi":"Kết quả của thí nghiệm đã khiến các nhà khoa học bất ngờ."},{"en":"As an experiment, I stopped using my phone for a week.","vi":"Để thử nghiệm, tôi đã ngừng dùng điện thoại trong một tuần."}]', '[{"phrase":"do an experiment"},{"phrase":"carry out an experiment"},{"phrase":"scientific experiment"}]', NULL, '/ɪkˈsperɪmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/exper/experiment__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 14, 'consideration', 'sự cân nhắc; sự quan tâm', 'noun', '[{"en":"After careful consideration, we decided not to buy the house.","vi":"Sau khi cân nhắc kỹ, chúng tôi quyết định không mua căn nhà đó."},{"en":"Please take my age into consideration when planning the trip.","vi":"Hãy tính đến tuổi tác của tôi khi lên kế hoạch cho chuyến đi."},{"en":"He shows no consideration for his neighbors when he plays loud music.","vi":"Anh ta chẳng hề quan tâm đến hàng xóm khi mở nhạc ầm ĩ."}]', '[{"phrase":"careful consideration"},{"phrase":"take into consideration"},{"phrase":"under consideration"}]', NULL, '/kənˌsɪdəˈreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconsideration__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 15, 'strange', 'lạ; kỳ lạ', 'adjective', '[{"en":"I heard a strange noise coming from the kitchen last night.","vi":"Đêm qua tôi nghe thấy một tiếng động lạ phát ra từ nhà bếp."},{"en":"It felt strange to be back at my old school.","vi":"Quay lại trường cũ khiến tôi có cảm giác thật lạ."},{"en":"Isn''t it strange that nobody answered the phone?","vi":"Không ai nghe điện thoại, chẳng phải lạ lắm sao?"}]', '[{"phrase":"strange noise"},{"phrase":"feel strange"},{"phrase":"strange feeling"}]', NULL, '/streɪndʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stran/strange__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 16, 'code', 'mã; bộ quy tắc', 'noun', '[{"en":"Enter the code we sent to your phone.","vi":"Hãy nhập mã mà chúng tôi đã gửi đến điện thoại của bạn."},{"en":"My brother writes code for a small software company.","vi":"Anh trai tôi viết mã cho một công ty phần mềm nhỏ."},{"en":"The school has a strict dress code for students.","vi":"Trường có quy tắc ăn mặc nghiêm ngặt dành cho học sinh."}]', '[{"phrase":"dress code"},{"phrase":"write code"},{"phrase":"security code"}]', NULL, '/kəʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cod/code_/code__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 17, 'possibly', 'có thể; có lẽ', 'adverb', '[{"en":"Could you possibly help me carry these boxes?","vi":"Bạn có thể giúp tôi khiêng mấy cái thùng này được không?"},{"en":"This is possibly the best pizza I have ever eaten.","vi":"Đây có lẽ là chiếc pizza ngon nhất tôi từng ăn."},{"en":"The package will arrive on Tuesday or possibly Wednesday.","vi":"Gói hàng sẽ đến vào thứ Ba hoặc có thể là thứ Tư."}]', '[{"phrase":"could possibly"},{"phrase":"can''t possibly"},{"phrase":"quite possibly"}]', NULL, '/ˈpɑːsəbli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pos/possi/possibly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 18, 'threat', 'mối đe dọa; lời đe dọa', 'noun', '[{"en":"Strong winds are a serious threat to homes near the coast.","vi":"Gió mạnh là mối đe dọa nghiêm trọng đối với những ngôi nhà gần bờ biển."},{"en":"The manager''s threat to cancel the project worried everyone.","vi":"Lời đe dọa hủy dự án của người quản lý khiến mọi người lo lắng."},{"en":"Computer viruses are a constant threat to our office network.","vi":"Virus máy tính là mối đe dọa thường trực đối với mạng máy tính ở văn phòng chúng tôi."}]', '[{"phrase":"serious threat"},{"phrase":"major threat"},{"phrase":"pose a threat"},{"phrase":"constant threat"}]', NULL, '/θret/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thr/threa/threat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 19, 'accident', 'tai nạn; sự tình cờ', 'noun', '[{"en":"She broke her arm in a bike accident last summer.","vi":"Cô ấy bị gãy tay trong một vụ tai nạn xe đạp mùa hè năm ngoái."},{"en":"Sorry, I deleted your file by accident.","vi":"Xin lỗi, tôi vô tình xóa mất tệp của bạn."},{"en":"We found this great little restaurant completely by accident.","vi":"Chúng tôi tìm thấy nhà hàng nhỏ tuyệt vời này hoàn toàn tình cờ."}]', '[{"phrase":"car accident"},{"phrase":"by accident"},{"phrase":"have an accident"}]', NULL, '/ˈæksɪdənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acc/accid/accident__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 20, 'impossible', 'không thể', 'adjective', '[{"en":"It''s impossible to sleep with all this noise outside.","vi":"Không thể nào ngủ được với chừng ấy tiếng ồn bên ngoài."},{"en":"Finding a cheap apartment downtown is almost impossible.","vi":"Tìm được một căn hộ rẻ ở trung tâm thành phố gần như là không thể."},{"en":"The instructions were impossible to understand without pictures.","vi":"Bản hướng dẫn không thể hiểu nổi nếu không có hình minh họa."}]', '[{"phrase":"almost impossible"},{"phrase":"nearly impossible"},{"phrase":"impossible task"}]', NULL, '/ɪmˈpɑːsəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imp/impos/impossible__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 21, 'revenue', 'doanh thu', 'noun', '[{"en":"The company''s revenue grew by ten percent last year.","vi":"Doanh thu của công ty đã tăng mười phần trăm vào năm ngoái."},{"en":"Tourism brings in most of the town''s revenue.","vi":"Du lịch mang lại phần lớn doanh thu cho thị trấn."},{"en":"We need to find new ways to increase revenue.","vi":"Chúng ta cần tìm những cách mới để tăng doanh thu."}]', '[{"phrase":"increase revenue"},{"phrase":"annual revenue"},{"phrase":"generate revenue"},{"phrase":"tax revenue"}]', NULL, '/ˈrevənuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/reven/revenue__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 22, 'enable', 'cho phép; giúp có thể', 'verb', '[{"en":"This app enables you to send money to friends instantly.","vi":"Ứng dụng này cho phép bạn chuyển tiền cho bạn bè ngay lập tức."},{"en":"The scholarship enabled her to study abroad for a year.","vi":"Học bổng đã giúp cô ấy có thể đi du học một năm."},{"en":"Good public transportation enables people to live without a car.","vi":"Giao thông công cộng tốt giúp mọi người có thể sống mà không cần ô tô."}]', '[{"phrase":"enable people to"},{"phrase":"enable users to"}]', 'enable somebody to do something', '/ɪˈneɪbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/ena/enabl/enable__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 23, 'afraid', 'sợ; e rằng', 'adjective', '[{"en":"My little sister is afraid of the dark.","vi":"Em gái tôi sợ bóng tối."},{"en":"Don''t be afraid to ask questions in class.","vi":"Đừng sợ đặt câu hỏi trong lớp."},{"en":"I''m afraid we don''t have any rooms left tonight.","vi":"Tôi e rằng tối nay chúng tôi không còn phòng trống nào."}]', '[{"phrase":"afraid of"},{"phrase":"I''m afraid"},{"phrase":"afraid to ask"}]', 'không dùng trước danh từ (không nói "an afraid child")', '/əˈfreɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/afr/afrai/afraid__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 24, 'active', 'năng động; tích cực; đang hoạt động', 'adjective', '[{"en":"My grandmother stays active by walking every morning.","vi":"Bà tôi giữ cho mình năng động bằng cách đi bộ mỗi sáng."},{"en":"He takes an active part in the school''s music club.","vi":"Cậu ấy tham gia tích cực vào câu lạc bộ âm nhạc của trường."},{"en":"Your account stays active if you log in once a month.","vi":"Tài khoản của bạn vẫn hoạt động nếu bạn đăng nhập mỗi tháng một lần."}]', '[{"phrase":"stay active"},{"phrase":"take an active part"},{"phrase":"active role"},{"phrase":"physically active"}]', NULL, '/ˈæktɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/activ/active__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 25, 'conclude', 'kết luận; kết thúc', 'verb', '[{"en":"The doctor concluded that the pain was caused by stress.","vi":"Bác sĩ kết luận rằng cơn đau là do căng thẳng gây ra."},{"en":"After reading the reviews, we concluded that the hotel wasn''t worth it.","vi":"Sau khi đọc các bài đánh giá, chúng tôi kết luận rằng khách sạn đó không đáng tiền."},{"en":"The meeting concluded with a short speech from the manager.","vi":"Cuộc họp kết thúc bằng một bài phát biểu ngắn của người quản lý."}]', '[{"phrase":"conclude that"},{"phrase":"conclude with"},{"phrase":"the report concludes"}]', NULL, '/kənˈkluːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconclude__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 26, 'religious', 'tôn giáo; sùng đạo', 'adjective', '[{"en":"The old town has many beautiful religious buildings.","vi":"Khu phố cổ có nhiều công trình tôn giáo đẹp."},{"en":"Many shops close for a few days during religious holidays.","vi":"Nhiều cửa hàng đóng cửa vài ngày trong các dịp lễ tôn giáo."},{"en":"My grandparents are very religious, but my parents are not.","vi":"Ông bà tôi rất sùng đạo, nhưng bố mẹ tôi thì không."}]', '[{"phrase":"religious holiday"},{"phrase":"religious beliefs"},{"phrase":"deeply religious"}]', NULL, '/rɪˈlɪdʒəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relig/religious__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 27, 'cancer', 'bệnh ung thư', 'noun', '[{"en":"Smoking greatly increases the risk of lung cancer.","vi":"Hút thuốc làm tăng đáng kể nguy cơ mắc ung thư phổi."},{"en":"Wearing sunscreen helps protect you from skin cancer.","vi":"Thoa kem chống nắng giúp bảo vệ bạn khỏi ung thư da."},{"en":"Scientists are developing new ways to treat cancer.","vi":"Các nhà khoa học đang phát triển những phương pháp mới để điều trị ung thư."}]', '[{"phrase":"lung cancer"},{"phrase":"skin cancer"},{"phrase":"treat cancer"},{"phrase":"cancer research"}]', NULL, '/ˈkænsər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/can/cance/cancer__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 28, 'convince', 'thuyết phục; làm cho tin', 'verb', '[{"en":"I finally convinced my parents to let me get a dog.","vi":"Cuối cùng tôi cũng thuyết phục được bố mẹ cho tôi nuôi một con chó."},{"en":"She tried to convince him that the plan would work.","vi":"Cô ấy cố thuyết phục anh ấy rằng kế hoạch sẽ thành công."},{"en":"I''m not convinced that this is the right decision.","vi":"Tôi không tin chắc rằng đây là quyết định đúng đắn."}]', '[{"phrase":"try to convince"},{"phrase":"fully convinced"},{"phrase":"not convinced"}]', NULL, '/kənˈvɪns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconv/xconvince__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 29, 'vary', 'thay đổi; khác nhau', 'verb', '[{"en":"Prices vary depending on the time of year.","vi":"Giá cả thay đổi tùy theo thời điểm trong năm."},{"en":"The size of the rooms varies from floor to floor.","vi":"Kích thước các phòng khác nhau tùy từng tầng."},{"en":"Try to vary your meals and eat more vegetables.","vi":"Hãy cố gắng thay đổi món ăn thường xuyên và ăn nhiều rau hơn."}]', '[{"phrase":"vary widely"},{"phrase":"vary greatly"},{"phrase":"vary in size"},{"phrase":"vary depending on"}]', NULL, '/ˈveri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/var/vary_/vary__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-12', 30, 'environmental', '(thuộc) môi trường', 'adjective', '[{"en":"Plastic waste is a huge environmental problem in many cities.","vi":"Rác thải nhựa là một vấn đề môi trường lớn ở nhiều thành phố."},{"en":"The company is trying to reduce its environmental impact.","vi":"Công ty đang cố gắng giảm tác động đến môi trường."},{"en":"She joined an environmental group at her university.","vi":"Cô ấy đã tham gia một nhóm hoạt động vì môi trường ở trường đại học."}]', '[{"phrase":"environmental problem"},{"phrase":"environmental impact"},{"phrase":"environmental protection"},{"phrase":"environmental group"}]', NULL, '/ɪnˌvaɪrənˈmentl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/env/envir/environmental__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-13', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 13', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 13);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 1, 'sun', 'mặt trời; ánh nắng', 'noun', '[{"en":"The sun rises earlier in summer than in winter.","vi":"Vào mùa hè, mặt trời mọc sớm hơn mùa đông."},{"en":"We sat in the sun and ate our lunch.","vi":"Chúng tôi ngồi dưới nắng và ăn trưa."},{"en":"Don''t forget to wear a hat when the sun is strong.","vi":"Đừng quên đội mũ khi trời nắng gắt."}]', '[{"phrase":"the sun rises"},{"phrase":"the sun sets"},{"phrase":"in the sun"},{"phrase":"the sun shines"}]', NULL, '/sʌn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sun/sun__/sun__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 2, 'healthy', 'khỏe mạnh; tốt cho sức khỏe', 'adjective', '[{"en":"My grandmother is still very healthy at the age of eighty.","vi":"Bà tôi vẫn rất khỏe mạnh ở tuổi tám mươi."},{"en":"Try to eat a healthy breakfast before you go to school.","vi":"Hãy cố gắng ăn một bữa sáng tốt cho sức khỏe trước khi đến trường."},{"en":"Walking every day is one of the easiest ways to stay healthy.","vi":"Đi bộ mỗi ngày là một trong những cách dễ nhất để giữ sức khỏe."}]', '[{"phrase":"healthy diet"},{"phrase":"healthy food"},{"phrase":"stay healthy"},{"phrase":"healthy lifestyle"}]', NULL, '/ˈhelθi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hea/healt/healthy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 3, 'blow', 'thổi; bị gió thổi bay', 'verb', '[{"en":"In winter, a cold wind blows from the north.","vi":"Vào mùa đông, gió lạnh thổi từ phía bắc."},{"en":"She blew out the candles on her birthday cake.","vi":"Cô ấy thổi tắt nến trên bánh sinh nhật."},{"en":"My hat blew away when we were standing on the bridge.","vi":"Mũ của tôi bị gió thổi bay khi chúng tôi đang đứng trên cầu."}]', '[{"phrase":"wind blows"},{"phrase":"blow out the candles"},{"phrase":"blow your nose"}]', 'blow – blew – blown', '/bləʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/blo/blow_/blow__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 4, 'volume', 'âm lượng; khối lượng, lượng; tập (sách)', 'noun', '[{"en":"Could you turn down the volume a little, please?","vi":"Bạn có thể vặn nhỏ âm lượng một chút được không?"},{"en":"The volume of traffic increases sharply during the holidays.","vi":"Lượng xe cộ tăng mạnh vào những ngày lễ."},{"en":"The second volume of the series will come out next year.","vi":"Tập thứ hai của bộ sách sẽ ra mắt vào năm sau."}]', '[{"phrase":"turn up the volume"},{"phrase":"turn down the volume"},{"phrase":"volume of traffic"},{"phrase":"large volume"}]', NULL, '/ˈvɑːljəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vol/volum/volume__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 5, 'location', 'vị trí; địa điểm', 'noun', '[{"en":"The hotel is in a great location near the beach.","vi":"Khách sạn nằm ở vị trí rất đẹp gần bãi biển."},{"en":"Please send me the exact location of the restaurant.","vi":"Hãy gửi cho tôi vị trí chính xác của nhà hàng."},{"en":"They changed the location of the meeting at the last minute.","vi":"Họ đã đổi địa điểm cuộc họp vào phút chót."}]', '[{"phrase":"exact location"},{"phrase":"central location"},{"phrase":"great location"}]', NULL, '/ləʊˈkeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loc/locat/location__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 6, 'invest', 'đầu tư', 'verb', '[{"en":"My parents invested all their savings in a small shop.","vi":"Bố mẹ tôi đã đầu tư toàn bộ tiền tiết kiệm vào một cửa hàng nhỏ."},{"en":"The company plans to invest more money in training its staff.","vi":"Công ty dự định đầu tư thêm tiền vào việc đào tạo nhân viên."},{"en":"You should invest time in learning a new language.","vi":"Bạn nên đầu tư thời gian vào việc học một ngôn ngữ mới."}]', '[{"phrase":"invest money"},{"phrase":"invest time"},{"phrase":"invest heavily in"}]', 'invest in something: đầu tư vào cái gì', '/ɪnˈvest/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inv/inves/invest__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 7, 'proceed', 'tiến hành; tiếp tục; đi tới (nơi nào)', 'verb', '[{"en":"After a short break, the meeting proceeded as planned.","vi":"Sau giờ nghỉ ngắn, cuộc họp tiếp tục diễn ra như kế hoạch."},{"en":"Passengers for the flight to Tokyo should proceed to gate 12.","vi":"Hành khách đi chuyến bay đến Tokyo xin vui lòng đến cửa số 12."},{"en":"We can proceed with the project once the budget is approved.","vi":"Chúng ta có thể tiến hành dự án khi ngân sách được duyệt."}]', '[{"phrase":"proceed with"},{"phrase":"proceed to"},{"phrase":"proceed as planned"}]', 'proceed with something: tiến hành việc gì', '/prəʊˈsiːd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proce/proceed__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 8, 'wash', 'rửa; giặt', 'verb', '[{"en":"Always wash your hands before you eat.","vi":"Luôn rửa tay trước khi ăn."},{"en":"I need to wash these clothes before our trip.","vi":"Tôi cần giặt chỗ quần áo này trước chuyến đi."},{"en":"Whose turn is it to wash the dishes tonight?","vi":"Tối nay đến lượt ai rửa bát?"}]', '[{"phrase":"wash your hands"},{"phrase":"wash the dishes"},{"phrase":"wash clothes"},{"phrase":"wash your hair"}]', NULL, '/wɑːʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/was/wash_/wash__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 9, 'actor', 'diễn viên', 'noun', '[{"en":"He wanted to become an actor when he was a child.","vi":"Hồi nhỏ, anh ấy muốn trở thành diễn viên."},{"en":"The actors are practicing for the school play tonight.","vi":"Các diễn viên đang tập cho vở kịch của trường tối nay."},{"en":"She is one of the best young actors in the country.","vi":"Cô ấy là một trong những diễn viên trẻ giỏi nhất cả nước."}]', '[{"phrase":"famous actor"},{"phrase":"young actor"},{"phrase":"leading actor"},{"phrase":"become an actor"}]', 'nữ diễn viên: actress', '/ˈæktər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/act/actor/actor__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 10, 'glad', 'vui mừng; sẵn lòng', 'adjective', '[{"en":"I''m glad you could come to my party.","vi":"Tôi rất vui vì bạn đã đến dự tiệc của tôi."},{"en":"We were glad to hear that your mother is feeling better.","vi":"Chúng tôi rất mừng khi nghe tin mẹ bạn đã khỏe hơn."},{"en":"I''d be glad to show you around the city this weekend.","vi":"Tôi sẵn lòng dẫn bạn đi tham quan thành phố vào cuối tuần này."}]', '[{"phrase":"glad to hear"},{"phrase":"be glad to help"},{"phrase":"really glad"}]', 'chỉ đứng sau động từ (be glad), không đứng trước danh từ', '/ɡlæd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gla/glad_/glad__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 11, 'tape', 'băng dính; băng (ghi âm, ghi hình)', 'noun', '[{"en":"I need some tape to close this box.","vi":"Tôi cần ít băng dính để dán cái hộp này lại."},{"en":"She fixed the torn page with a small piece of tape.","vi":"Cô ấy dán lại trang giấy bị rách bằng một miếng băng dính nhỏ."},{"en":"My dad still has old tapes of songs he recorded from the radio.","vi":"Bố tôi vẫn còn những cuộn băng cũ thu các bài hát từ đài phát thanh."}]', '[{"phrase":"piece of tape"},{"phrase":"sticky tape"},{"phrase":"masking tape"}]', NULL, '/teɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tap/tape_/tape__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 12, 'whereas', 'trong khi (đó); còn', 'conjunction', '[{"en":"I love spicy food, whereas my brother can''t eat it at all.","vi":"Tôi rất thích đồ ăn cay, trong khi anh trai tôi hoàn toàn không ăn được."},{"en":"Some students learn quickly, whereas others need more time.","vi":"Một số học sinh học nhanh, còn những em khác cần nhiều thời gian hơn."},{"en":"Whereas the city is noisy and crowded, the village is peaceful.","vi":"Trong khi thành phố ồn ào và đông đúc thì ngôi làng lại yên bình."}]', '[{"phrase":"whereas others"},{"phrase":"whereas in the past"}]', 'dùng để nêu hai ý trái ngược; trang trọng hơn while', '/ˌwerˈæz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/whe/where/whereas__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 13, 'opposite', 'đối diện; trái ngược', 'adjective', '[{"en":"They live in the house on the opposite side of the road.","vi":"Họ sống trong ngôi nhà ở phía bên kia đường."},{"en":"My sister and I have opposite opinions about almost everything.","vi":"Chị tôi và tôi có ý kiến trái ngược nhau về hầu hết mọi chuyện."},{"en":"The two cars were driving in opposite directions.","vi":"Hai chiếc xe đang chạy theo hai hướng ngược nhau."}]', '[{"phrase":"opposite side"},{"phrase":"opposite direction"},{"phrase":"the exact opposite"}]', 'cũng là giới từ: opposite the station (đối diện nhà ga)', '/ˈɑːpəzɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opp/oppos/opposite__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 14, 'stone', 'đá; hòn đá', 'noun', '[{"en":"The old bridge is made of stone.","vi":"Cây cầu cổ được xây bằng đá."},{"en":"The children were throwing stones into the river.","vi":"Bọn trẻ đang ném đá xuống sông."},{"en":"I got a small stone in my shoe while we were hiking.","vi":"Tôi bị một viên đá nhỏ lọt vào giày khi chúng tôi đang đi bộ đường dài."}]', '[{"phrase":"made of stone"},{"phrase":"stone wall"},{"phrase":"throw stones"}]', 'chất liệu đá: không đếm được; hòn đá: đếm được', '/stəʊn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/stone/stone__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 15, 'sum', 'khoản tiền; tổng số', 'noun', '[{"en":"They paid a large sum of money for the old house.","vi":"Họ đã trả một khoản tiền lớn cho ngôi nhà cũ."},{"en":"She saved a small sum every month for her trip.","vi":"Cô ấy tiết kiệm một khoản tiền nhỏ mỗi tháng cho chuyến đi."},{"en":"The sum of five and seven is twelve.","vi":"Tổng của năm và bảy là mười hai."}]', '[{"phrase":"sum of money"},{"phrase":"large sum"},{"phrase":"small sum"}]', 'sum up: tóm tắt', '/sʌm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sum/sum__/sum__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 16, 'murder', 'vụ giết người, án mạng; tội giết người', 'noun', '[{"en":"The police are still investigating the murder.","vi":"Cảnh sát vẫn đang điều tra vụ giết người."},{"en":"The film is about a detective trying to solve a murder.","vi":"Bộ phim kể về một thám tử đang cố gắng phá một vụ án mạng."},{"en":"I stayed up late reading a murder mystery novel.","vi":"Tôi thức khuya đọc một cuốn tiểu thuyết trinh thám về án mạng."}]', '[{"phrase":"murder case"},{"phrase":"murder mystery"},{"phrase":"solve a murder"}]', 'cũng là động từ: giết (người) có chủ ý', '/ˈmɜːrdər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mur/murde/murder__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 17, 'monitor', 'theo dõi; giám sát', 'verb', '[{"en":"Nurses monitor the patients carefully throughout the night.","vi":"Các y tá theo dõi bệnh nhân cẩn thận suốt đêm."},{"en":"This app helps you monitor how much you sleep.","vi":"Ứng dụng này giúp bạn theo dõi mình ngủ được bao nhiêu."},{"en":"Weekly tests help teachers monitor progress throughout the term.","vi":"Các bài kiểm tra hằng tuần giúp giáo viên theo dõi sự tiến bộ trong suốt học kỳ."}]', '[{"phrase":"monitor progress"},{"phrase":"closely monitor"},{"phrase":"monitor the situation"}]', 'cũng là danh từ: màn hình (máy tính)', '/ˈmɑːnɪtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mon/monit/monitor__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 18, 'soldier', 'người lính, binh sĩ', 'noun', '[{"en":"Her grandfather was a soldier for twenty years.","vi":"Ông của cô ấy đã làm lính suốt hai mươi năm."},{"en":"The soldiers marched through the town during the parade.","vi":"Những người lính diễu hành qua thị trấn trong buổi diễu binh."},{"en":"My cousin wants to become a soldier after he finishes school.","vi":"Anh họ tôi muốn trở thành người lính sau khi học xong."}]', '[{"phrase":"young soldier"},{"phrase":"become a soldier"},{"phrase":"former soldier"}]', NULL, '/ˈsəʊldʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sol/soldi/soldier__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 19, 'finance', 'tài chính', 'noun', '[{"en":"She wants to work in finance after she graduates.","vi":"Cô ấy muốn làm trong ngành tài chính sau khi tốt nghiệp."},{"en":"We need to talk about our family finances this month.","vi":"Tháng này chúng ta cần bàn về tình hình tài chính của gia đình."},{"en":"He is studying finance at a university in Singapore.","vi":"Anh ấy đang học ngành tài chính tại một trường đại học ở Singapore."}]', '[{"phrase":"personal finance"},{"phrase":"finance department"},{"phrase":"work in finance"}]', 'finances (số nhiều): tình hình tiền bạc', '/ˈfaɪnæns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/finan/finance__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 20, 'hate', 'ghét', 'verb', '[{"en":"I really hate getting up early on cold mornings.","vi":"Tôi rất ghét phải dậy sớm vào những buổi sáng lạnh."},{"en":"My little brother hates vegetables, especially carrots.","vi":"Em trai tôi ghét rau, nhất là cà rốt."},{"en":"She hated her first job, but she learned a lot from it.","vi":"Cô ấy ghét công việc đầu tiên, nhưng đã học được rất nhiều từ nó."}]', '[{"phrase":"really hate"},{"phrase":"hate it when"},{"phrase":"hate to say"}]', 'hate + V-ing / to V', '/heɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hat/hate_/hate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 21, 'egg', 'trứng', 'noun', '[{"en":"I usually have a fried egg and toast for breakfast.","vi":"Tôi thường ăn một quả trứng chiên với bánh mì nướng vào bữa sáng."},{"en":"Can you buy a dozen eggs on your way home?","vi":"Bạn mua giúp một tá trứng trên đường về nhé?"},{"en":"The bird laid three eggs in the nest.","vi":"Con chim đã đẻ ba quả trứng trong tổ."}]', '[{"phrase":"fried egg"},{"phrase":"boiled egg"},{"phrase":"lay eggs"}]', NULL, '/eɡ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/egg/egg__/egg__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 22, 'concert', 'buổi hòa nhạc', 'noun', '[{"en":"We''re going to a rock concert on Saturday night.","vi":"Tối thứ Bảy chúng tôi sẽ đi xem một buổi hòa nhạc rock."},{"en":"The tickets for the concert sold out in an hour.","vi":"Vé của buổi hòa nhạc đã bán hết chỉ trong một giờ."},{"en":"My daughter will play the piano at the school concert.","vi":"Con gái tôi sẽ chơi piano trong buổi hòa nhạc của trường."}]', '[{"phrase":"go to a concert"},{"phrase":"live concert"},{"phrase":"rock concert"},{"phrase":"concert tickets"}]', NULL, '/ˈkɑːnsərt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconc/xconcert__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 23, 'shock', 'cú sốc; sự bàng hoàng', 'noun', '[{"en":"The news of the factory closing came as a shock to everyone.","vi":"Tin nhà máy đóng cửa là một cú sốc đối với mọi người."},{"en":"She was still in shock after the car accident.","vi":"Cô ấy vẫn còn bàng hoàng sau vụ tai nạn xe hơi."},{"en":"It was a real shock to see how expensive everything was.","vi":"Thật là sốc khi thấy mọi thứ đắt đỏ đến thế nào."}]', '[{"phrase":"come as a shock"},{"phrase":"in shock"},{"phrase":"a real shock"}]', NULL, '/ʃɑːk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shock/shock__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 24, 'comfortable', 'thoải mái; dễ chịu', 'adjective', '[{"en":"These shoes are really comfortable for long walks.","vi":"Đôi giày này đi bộ đường dài rất thoải mái."},{"en":"Please make yourself comfortable while I make some tea.","vi":"Bạn cứ tự nhiên nhé, để tôi đi pha ít trà."},{"en":"I don''t feel comfortable speaking in front of large groups.","vi":"Tôi không thấy thoải mái khi nói trước đông người."}]', '[{"phrase":"make yourself comfortable"},{"phrase":"feel comfortable"},{"phrase":"comfortable shoes"},{"phrase":"comfortable chair"}]', NULL, '/ˈkʌmftəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comfo/comfortable__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 25, 'usual', 'thường lệ; thông thường', 'adjective', '[{"en":"Let''s meet at the usual place after work.","vi":"Sau giờ làm mình gặp nhau ở chỗ quen nhé."},{"en":"The bus was later than usual this morning.","vi":"Sáng nay xe buýt đến muộn hơn thường lệ."},{"en":"As usual, my brother forgot to call our mother on her birthday.","vi":"Như thường lệ, anh trai tôi lại quên gọi điện cho mẹ vào ngày sinh nhật của mẹ."}]', '[{"phrase":"as usual"},{"phrase":"than usual"},{"phrase":"the usual place"}]', NULL, '/ˈjuːʒuəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/usu/usual/usual__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 26, 'carefully', 'cẩn thận; kỹ lưỡng', 'adverb', '[{"en":"Please read the instructions carefully before you start.","vi":"Hãy đọc kỹ hướng dẫn trước khi bắt đầu."},{"en":"She carefully placed the glasses on the top shelf.","vi":"Cô ấy cẩn thận đặt những chiếc ly lên kệ trên cùng."},{"en":"You should drive carefully because the roads are icy tonight.","vi":"Bạn nên lái xe cẩn thận vì tối nay đường đóng băng."}]', '[{"phrase":"read carefully"},{"phrase":"listen carefully"},{"phrase":"drive carefully"},{"phrase":"think carefully"}]', NULL, '/ˈkerfəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/caref/carefully__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 27, 'pack', 'xếp đồ (vào vali, túi); đóng gói', 'verb', '[{"en":"It only took me ten minutes to pack a bag for the weekend.","vi":"Tôi chỉ mất mười phút để xếp đồ vào túi cho chuyến đi cuối tuần."},{"en":"I always pack too many clothes when I travel.","vi":"Lúc nào đi du lịch tôi cũng xếp quá nhiều quần áo vào vali."},{"en":"Workers pack the fruit into boxes before it leaves the farm.","vi":"Công nhân đóng trái cây vào thùng trước khi chuyển ra khỏi trang trại."}]', '[{"phrase":"pack a bag"},{"phrase":"pack a suitcase"},{"phrase":"pack up"},{"phrase":"pack your things"}]', NULL, '/pæk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pac/pack_/pack__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 28, 'recall', 'nhớ lại', 'verb', '[{"en":"I can''t recall the name of the hotel we stayed at.","vi":"Tôi không nhớ nổi tên khách sạn mà chúng tôi đã ở."},{"en":"She recalled meeting him at a friend''s wedding years ago.","vi":"Cô ấy nhớ lại đã gặp anh ấy ở đám cưới của một người bạn nhiều năm trước."},{"en":"As far as I can recall, the meeting started at nine.","vi":"Theo như tôi nhớ thì cuộc họp bắt đầu lúc chín giờ."}]', '[{"phrase":"can''t recall"},{"phrase":"as far as I can recall"},{"phrase":"clearly recall"}]', 'recall + V-ing: nhớ lại đã làm gì', '/rɪˈkɔːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recal/recall__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 29, 'wine', 'rượu vang', 'noun', '[{"en":"Would you like a glass of red wine with dinner?","vi":"Bạn có muốn một ly rượu vang đỏ trong bữa tối không?"},{"en":"This region is famous for its excellent wine.","vi":"Vùng này nổi tiếng với rượu vang hảo hạng."},{"en":"We bought a bottle of wine as a gift for our hosts.","vi":"Chúng tôi mua một chai rượu vang làm quà cho chủ nhà."}]', '[{"phrase":"glass of wine"},{"phrase":"bottle of wine"},{"phrase":"red wine"},{"phrase":"white wine"}]', NULL, '/waɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/win/wine_/wine__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-13', 30, 'camera', 'máy ảnh; camera', 'noun', '[{"en":"I forgot to bring my camera on our vacation.","vi":"Tôi quên mang theo máy ảnh trong kỳ nghỉ của chúng tôi."},{"en":"There are security cameras at every door of the store.","vi":"Có camera an ninh ở mọi cửa ra vào của cửa hàng."},{"en":"She smiled at the camera when her father took a photo.","vi":"Cô bé mỉm cười nhìn vào máy ảnh khi bố chụp hình."}]', '[{"phrase":"digital camera"},{"phrase":"security camera"},{"phrase":"smile at the camera"}]', NULL, '/ˈkæmrə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cam/camer/camera__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-14', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 14', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 14);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 1, 'swim', 'bơi', 'verb', '[{"en":"My little brother learned to swim when he was five.","vi":"Em trai tôi học bơi khi lên năm tuổi."},{"en":"We swam in the lake every morning during our vacation.","vi":"Chúng tôi bơi ở hồ mỗi sáng trong kỳ nghỉ."},{"en":"Do you want to go swimming after work today?","vi":"Hôm nay tan làm bạn có muốn đi bơi không?"}]', '[{"phrase":"learn to swim"},{"phrase":"go swimming"},{"phrase":"swim in the sea"}]', 'swim – swam – swum', '/swɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/swi/swim_/swim__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 2, 'manufacture', 'sản xuất; chế tạo', 'verb', '[{"en":"This factory manufactures parts for cars and trucks.","vi":"Nhà máy này sản xuất phụ tùng cho ô tô và xe tải."},{"en":"Most of our phones are manufactured in Asia.","vi":"Phần lớn điện thoại của chúng tôi được sản xuất ở châu Á."},{"en":"The company started to manufacture its own furniture last year.","vi":"Năm ngoái công ty bắt đầu tự sản xuất đồ nội thất."}]', '[{"phrase":"manufacture goods"},{"phrase":"manufacture products"},{"phrase":"locally manufactured"}]', NULL, '/ˌmænjuˈfæktʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manuf/manufacture__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 3, 'theater', 'nhà hát; rạp chiếu phim', 'noun', '[{"en":"We saw a wonderful play at the theater last night.","vi":"Tối qua chúng tôi xem một vở kịch tuyệt vời ở nhà hát."},{"en":"The new movie opens in theaters next Friday.","vi":"Bộ phim mới sẽ ra rạp vào thứ Sáu tới."},{"en":"Please turn off your phone before you enter the theater.","vi":"Vui lòng tắt điện thoại trước khi vào rạp."}]', '[{"phrase":"go to the theater"},{"phrase":"movie theater"},{"phrase":"theater tickets"}]', 'Mỹ: theater · Anh: theatre', '/ˈθiːətər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 4, 'cycle', 'chu kỳ; chu trình; vòng', 'noun', '[{"en":"The washing machine takes about an hour to finish one cycle.","vi":"Máy giặt mất khoảng một tiếng để chạy xong một chu trình."},{"en":"Children learn about the life cycle of a butterfly at school.","vi":"Trẻ em học về vòng đời của loài bướm ở trường."},{"en":"It''s hard to break the cycle of staying up late.","vi":"Thật khó để thoát khỏi vòng lặp thức khuya."}]', '[{"phrase":"life cycle"},{"phrase":"break the cycle"},{"phrase":"vicious cycle"}]', NULL, '/ˈsaɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cyc/cycle/cycle__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 5, 'coffee', 'cà phê', 'noun', '[{"en":"I always have a cup of coffee before I start work.","vi":"Tôi luôn uống một tách cà phê trước khi bắt đầu làm việc."},{"en":"Would you like to get coffee with me this afternoon?","vi":"Chiều nay bạn có muốn đi uống cà phê với tôi không?"},{"en":"She drinks her coffee black, without any sugar or milk.","vi":"Cô ấy uống cà phê đen, không đường cũng không sữa."}]', '[{"phrase":"a cup of coffee"},{"phrase":"black coffee"},{"phrase":"make coffee"},{"phrase":"coffee shop"}]', NULL, '/ˈkɔːfi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cof/coffe/coffee__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 6, 'totally', 'hoàn toàn', 'adverb', '[{"en":"I totally forgot about our meeting this morning.","vi":"Tôi quên hẳn cuộc họp của chúng ta sáng nay."},{"en":"The town looks totally different from ten years ago.","vi":"Thị trấn trông hoàn toàn khác so với mười năm trước."},{"en":"You''re totally right, we should leave a bit earlier.","vi":"Bạn hoàn toàn đúng, chúng ta nên đi sớm hơn một chút."}]', '[{"phrase":"totally different"},{"phrase":"totally agree"},{"phrase":"totally forget"}]', NULL, '/ˈtəʊtəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tot/total/totally__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 7, 'museum', 'bảo tàng', 'noun', '[{"en":"We spent the whole afternoon at the art museum.","vi":"Chúng tôi dành cả buổi chiều ở bảo tàng nghệ thuật."},{"en":"The museum is free for students on Sundays.","vi":"Bảo tàng miễn phí cho sinh viên vào Chủ nhật."},{"en":"Have you ever visited the history museum in the city center?","vi":"Bạn đã bao giờ tham quan bảo tàng lịch sử ở trung tâm thành phố chưa?"}]', '[{"phrase":"visit a museum"},{"phrase":"art museum"},{"phrase":"history museum"}]', NULL, '/mjuˈziːəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mus/museu/museum__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 8, 'visitor', 'khách; du khách', 'noun', '[{"en":"The park gets thousands of visitors every summer.","vi":"Công viên đón hàng nghìn du khách mỗi mùa hè."},{"en":"We don''t have many visitors since we moved to the country.","vi":"Từ khi chuyển về quê, chúng tôi không có nhiều khách đến chơi."},{"en":"All visitors must sign in at the front desk.","vi":"Tất cả khách phải đăng ký ở quầy lễ tân."}]', '[{"phrase":"foreign visitors"},{"phrase":"attract visitors"},{"phrase":"regular visitor"}]', NULL, '/ˈvɪzɪtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vis/visit/visitor__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 9, 'freedom', 'sự tự do', 'noun', '[{"en":"Working from home gives me more freedom to plan my day.","vi":"Làm việc tại nhà cho tôi nhiều tự do hơn để sắp xếp ngày của mình."},{"en":"Teenagers often want more freedom from their parents.","vi":"Thanh thiếu niên thường muốn được bố mẹ cho tự do hơn."},{"en":"After leaving home, she finally enjoyed her freedom.","vi":"Sau khi rời nhà, cuối cùng cô ấy đã được tận hưởng sự tự do."}]', '[{"phrase":"freedom to do something"},{"phrase":"enjoy freedom"},{"phrase":"personal freedom"}]', 'không đếm được', '/ˈfriːdəm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fre/freed/freedom__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 10, 'construction', 'sự xây dựng; ngành xây dựng', 'noun', '[{"en":"The new bridge is still under construction.","vi":"Cây cầu mới vẫn đang được xây dựng."},{"en":"My uncle has worked in construction for twenty years.","vi":"Chú tôi đã làm trong ngành xây dựng hai mươi năm."},{"en":"Construction of the hospital will begin next spring.","vi":"Việc xây dựng bệnh viện sẽ bắt đầu vào mùa xuân năm sau."}]', '[{"phrase":"under construction"},{"phrase":"construction work"},{"phrase":"construction site"}]', NULL, '/kənˈstrʌkʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcons/xconstruction__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 11, 'dear', 'thân mến; thân yêu; quý giá', 'adjective', '[{"en":"She started the letter with \"Dear Grandma.\"","vi":"Cô ấy mở đầu lá thư bằng \"Bà thân yêu\"."},{"en":"He has been a dear friend of mine since high school.","vi":"Anh ấy là bạn thân yêu của tôi từ hồi cấp ba."},{"en":"This old photo is very dear to me.","vi":"Bức ảnh cũ này rất quý giá với tôi."}]', '[{"phrase":"dear friend"},{"phrase":"Dear Sir or Madam"},{"phrase":"dear to someone"}]', NULL, '/dɪr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dea/dear_/dear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 12, 'objective', 'mục tiêu; khách quan', 'noun', '[{"en":"Our main objective this year is to find more customers.","vi":"Mục tiêu chính của chúng tôi năm nay là tìm thêm khách hàng."},{"en":"The teacher explained the objectives of the course on the first day.","vi":"Thầy giáo giải thích các mục tiêu của khóa học vào ngày đầu tiên."},{"en":"It''s hard to stay objective when your family is involved.","vi":"Thật khó giữ khách quan khi chuyện liên quan đến gia đình mình."}]', '[{"phrase":"main objective"},{"phrase":"achieve an objective"},{"phrase":"set objectives"}]', NULL, '/əbˈdʒektɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/obj/objec/objective__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 13, 'moreover', 'hơn nữa; ngoài ra', 'adverb', '[{"en":"The hotel was cheap and, moreover, it was very close to the beach.","vi":"Khách sạn rẻ và hơn nữa còn rất gần bãi biển."},{"en":"The plan is too expensive; moreover, it would take years to finish.","vi":"Kế hoạch này quá tốn kém; ngoài ra, phải mất nhiều năm mới hoàn thành."},{"en":"Moreover, the new system will save us a lot of time.","vi":"Hơn nữa, hệ thống mới sẽ giúp chúng ta tiết kiệm rất nhiều thời gian."}]', '[{"phrase":"and moreover"},{"phrase":"moreover, it"}]', 'Thường dùng trong văn viết trang trọng', '/mɔːrˈəʊvər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mor/moreo/moreover__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 14, 'onto', 'lên trên; lên', 'preposition', '[{"en":"The cat jumped onto the kitchen table.","vi":"Con mèo nhảy lên bàn bếp."},{"en":"Be careful when you step onto the train.","vi":"Hãy cẩn thận khi bước lên tàu."},{"en":"He poured some water onto the plants in the garden.","vi":"Anh ấy tưới một ít nước lên cây trong vườn."}]', '[{"phrase":"jump onto"},{"phrase":"step onto"},{"phrase":"climb onto"},{"phrase":"hold onto"}]', NULL, '/ˈɑːntə/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/ont/onto_/onto__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 15, 'historical', '(thuộc) lịch sử', 'adjective', '[{"en":"My father loves reading historical novels in the evening.","vi":"Bố tôi rất thích đọc tiểu thuyết lịch sử vào buổi tối."},{"en":"The old town has many important historical buildings.","vi":"Khu phố cổ có nhiều công trình lịch sử quan trọng."},{"en":"The film is based on real historical events.","vi":"Bộ phim dựa trên các sự kiện lịch sử có thật."}]', '[{"phrase":"historical events"},{"phrase":"historical buildings"},{"phrase":"historical novel"},{"phrase":"historical site"}]', 'historical (liên quan đến lịch sử) ≠ historic (có ý nghĩa lịch sử)', '/hɪˈstɔːrɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/his/histo/historical__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 16, 'oppose', 'phản đối; chống lại', 'verb', '[{"en":"Many parents oppose the plan to close the school.","vi":"Nhiều phụ huynh phản đối kế hoạch đóng cửa trường."},{"en":"I''m strongly opposed to building a road through the park.","vi":"Tôi kịch liệt phản đối việc làm đường xuyên qua công viên."},{"en":"Local people opposed the new factory from the start.","vi":"Người dân địa phương đã phản đối nhà máy mới ngay từ đầu."}]', '[{"phrase":"strongly oppose"},{"phrase":"oppose a plan"},{"phrase":"be opposed to"}]', 'be opposed to + V-ing', '/əˈpəʊz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/opp/oppos/oppose__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 17, 'branch', 'cành cây; chi nhánh', 'noun', '[{"en":"A small bird was sitting on a branch outside my window.","vi":"Một chú chim nhỏ đang đậu trên cành cây ngoài cửa sổ của tôi."},{"en":"The bank has a branch near our office.","vi":"Ngân hàng có một chi nhánh gần văn phòng chúng tôi."},{"en":"She works at the company''s branch in Singapore.","vi":"Cô ấy làm việc tại chi nhánh của công ty ở Singapore."}]', '[{"phrase":"tree branch"},{"phrase":"local branch"},{"phrase":"branch office"},{"phrase":"open a branch"}]', NULL, '/bræntʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bra/branc/branch__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 18, 'vehicle', 'xe cộ; phương tiện', 'noun', '[{"en":"Please don''t leave your vehicle in front of the gate.","vi":"Vui lòng không để xe trước cổng."},{"en":"More people are buying electric vehicles these days.","vi":"Ngày nay ngày càng nhiều người mua xe điện."},{"en":"The road is closed to all vehicles on Sunday mornings.","vi":"Con đường cấm tất cả xe cộ vào sáng Chủ nhật."}]', '[{"phrase":"electric vehicle"},{"phrase":"motor vehicle"},{"phrase":"drive a vehicle"}]', NULL, '/ˈviːəkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/veh/vehic/vehicle__us_5.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 19, 'scientist', 'nhà khoa học', 'noun', '[{"en":"My daughter wants to be a scientist when she grows up.","vi":"Con gái tôi muốn trở thành nhà khoa học khi lớn lên."},{"en":"Scientists have found a new kind of fish in the river.","vi":"Các nhà khoa học đã phát hiện một loài cá mới trên sông."},{"en":"A team of scientists is studying the effects of the hot weather.","vi":"Một nhóm nhà khoa học đang nghiên cứu ảnh hưởng của thời tiết nóng."}]', '[{"phrase":"team of scientists"},{"phrase":"scientists believe"},{"phrase":"research scientist"}]', NULL, '/ˈsaɪəntɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sci/scien/scientist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 20, 'route', 'tuyến đường; lộ trình', 'noun', '[{"en":"What''s the fastest route to the airport from here?","vi":"Từ đây đến sân bay đi đường nào nhanh nhất?"},{"en":"This bus route goes past the university.","vi":"Tuyến xe buýt này đi ngang qua trường đại học."},{"en":"We took a different route home to avoid the traffic.","vi":"Chúng tôi đi đường khác về nhà để tránh kẹt xe."}]', '[{"phrase":"bus route"},{"phrase":"take a route"},{"phrase":"the fastest route"}]', NULL, '/ruːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rou/route/route__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 21, 'bind', 'buộc; ràng buộc; đóng (sách)', 'verb', '[{"en":"She bound the old letters together with a piece of string.","vi":"Cô ấy buộc những lá thư cũ lại với nhau bằng một sợi dây."},{"en":"Both sides are bound by the terms of the contract.","vi":"Cả hai bên đều bị ràng buộc bởi các điều khoản của hợp đồng."},{"en":"The old book was bound in brown leather.","vi":"Cuốn sách cũ được đóng bìa bằng da màu nâu."}]', '[{"phrase":"bind together"},{"phrase":"be bound by"},{"phrase":"legally binding"}]', 'bind – bound – bound', '/baɪnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bin/bind_/bind__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 22, 'belong', 'thuộc về; đúng chỗ', 'verb', '[{"en":"Excuse me, does this umbrella belong to you?","vi":"Xin lỗi, cái ô này có phải của bạn không?"},{"en":"These books belong on the top shelf.","vi":"Mấy cuốn sách này phải để ở kệ trên cùng."},{"en":"After a few months, I really felt that I belonged here.","vi":"Sau vài tháng, tôi thật sự cảm thấy mình thuộc về nơi này."}]', '[{"phrase":"belong to"},{"phrase":"a sense of belonging"},{"phrase":"belong together"}]', 'belong to + người/nhóm', '/bɪˈlɔːŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bel/belon/belong__us_6.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 23, 'taste', 'vị; khẩu vị; gu', 'noun', '[{"en":"I don''t like the taste of this medicine.","vi":"Tôi không thích vị của thuốc này."},{"en":"The soup has a slightly sweet taste.","vi":"Món súp có vị hơi ngọt."},{"en":"My sister has great taste in clothes.","vi":"Chị tôi rất có gu ăn mặc."}]', '[{"phrase":"sweet taste"},{"phrase":"good taste"},{"phrase":"taste in music"}]', NULL, '/teɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tas/taste/taste__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 24, 'tonight', 'tối nay; đêm nay', 'adverb', '[{"en":"What do you want to have for dinner tonight?","vi":"Tối nay bạn muốn ăn gì?"},{"en":"I''m too tired to go out tonight.","vi":"Tối nay tôi mệt quá, không muốn ra ngoài."},{"en":"It''s going to be very cold tonight, so take a jacket.","vi":"Đêm nay trời sẽ rất lạnh, nên mang theo áo khoác nhé."}]', '[{"phrase":"see you tonight"},{"phrase":"later tonight"},{"phrase":"go out tonight"}]', NULL, '/təˈnaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ton/tonig/tonight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 25, 'fashion', 'thời trang; mốt', 'noun', '[{"en":"She is very interested in fashion and design.","vi":"Cô ấy rất quan tâm đến thời trang và thiết kế."},{"en":"Long skirts are back in fashion this year.","vi":"Váy dài lại trở thành mốt trong năm nay."},{"en":"My brother never cares about the latest fashions.","vi":"Anh tôi chẳng bao giờ quan tâm đến mốt mới nhất."}]', '[{"phrase":"in fashion"},{"phrase":"out of fashion"},{"phrase":"fashion show"},{"phrase":"latest fashion"}]', NULL, '/ˈfæʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fas/fashi/fashion__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 26, 'danger', 'sự nguy hiểm; mối nguy; nguy cơ', 'noun', '[{"en":"The doctors say he is now out of danger.","vi":"Các bác sĩ nói anh ấy giờ đã qua cơn nguy hiểm."},{"en":"Children don''t always understand the dangers of busy roads.","vi":"Trẻ em không phải lúc nào cũng hiểu mối nguy hiểm của những con đường đông xe."},{"en":"There is a danger that the river will flood this week.","vi":"Tuần này có nguy cơ sông sẽ bị lũ."}]', '[{"phrase":"in danger"},{"phrase":"out of danger"},{"phrase":"danger of"},{"phrase":"serious danger"}]', NULL, '/ˈdeɪndʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dan/dange/danger__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 27, 'bomb', 'quả bom', 'noun', '[{"en":"Workers found an old bomb while digging near the river.","vi":"Công nhân tìm thấy một quả bom cũ khi đang đào gần bờ sông."},{"en":"The police closed the street after a bomb warning.","vi":"Cảnh sát đã phong tỏa con phố sau một cảnh báo có bom."},{"en":"Experts safely removed the bomb from the building site.","vi":"Các chuyên gia đã di dời quả bom khỏi công trường một cách an toàn."}]', '[{"phrase":"bomb warning"},{"phrase":"bomb squad"},{"phrase":"drop a bomb"}]', NULL, '/bɑːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bom/bomb_/bomb__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 28, 'army', 'quân đội', 'noun', '[{"en":"My grandfather joined the army when he was eighteen.","vi":"Ông tôi nhập ngũ khi mười tám tuổi."},{"en":"The army helped people leave the flooded villages.","vi":"Quân đội đã giúp người dân rời khỏi những ngôi làng bị ngập lụt."},{"en":"Her brother is an officer in the army.","vi":"Anh trai cô ấy là sĩ quan trong quân đội."}]', '[{"phrase":"join the army"},{"phrase":"in the army"},{"phrase":"army officer"}]', NULL, '/ˈɑːrmi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arm/army_/army__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 29, 'dangerous', 'nguy hiểm', 'adjective', '[{"en":"It''s dangerous to use your phone while driving.","vi":"Dùng điện thoại khi lái xe rất nguy hiểm."},{"en":"Some of the snakes in this area are very dangerous.","vi":"Một số loài rắn ở khu vực này rất nguy hiểm."},{"en":"The ice on the lake is thin and dangerous to walk on.","vi":"Băng trên hồ mỏng và đi lên rất nguy hiểm."}]', '[{"phrase":"extremely dangerous"},{"phrase":"dangerous situation"},{"phrase":"dangerous to do something"}]', NULL, '/ˈdeɪndʒərəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dan/dange/dangerous__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-14', 30, 'decrease', 'giảm; giảm bớt', 'verb', '[{"en":"The number of students in the village school has decreased.","vi":"Số học sinh ở trường làng đã giảm."},{"en":"Regular exercise can decrease your risk of heart disease.","vi":"Tập thể dục đều đặn có thể giảm nguy cơ mắc bệnh tim."},{"en":"Sales decreased by ten percent last month.","vi":"Doanh số đã giảm mười phần trăm vào tháng trước."}]', '[{"phrase":"decrease by"},{"phrase":"decrease the risk"},{"phrase":"sharply decrease"}]', 'decrease ≠ increase (tăng)', '/dɪˈkriːs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dec/decre/decrease__us_4_rr.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-15', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 15', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 15);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 1, 'hurt', 'làm đau; bị đau; làm tổn thương', 'verb', '[{"en":"I hurt my back while moving the sofa last week.","vi":"Tôi bị đau lưng khi chuyển chiếc ghế sofa tuần trước."},{"en":"My feet really hurt after walking around the city all day.","vi":"Chân tôi đau nhức sau khi đi bộ quanh thành phố cả ngày."},{"en":"It hurt her feelings when nobody remembered her birthday.","vi":"Việc không ai nhớ sinh nhật cô ấy đã làm cô ấy tổn thương."}]', '[{"phrase":"hurt your back"},{"phrase":"get hurt"},{"phrase":"hurt someone''s feelings"}]', 'hurt – hurt – hurt', '/hɜːrt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hur/hurt_/hurt__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 2, 'council', 'hội đồng', 'noun', '[{"en":"The local council plans to build a new park near the school.","vi":"Hội đồng địa phương dự định xây một công viên mới gần trường học."},{"en":"She was elected to the city council last year.","vi":"Cô ấy được bầu vào hội đồng thành phố năm ngoái."},{"en":"The student council meets every Friday to discuss school events.","vi":"Hội đồng học sinh họp vào mỗi thứ Sáu để bàn về các sự kiện của trường."}]', '[{"phrase":"city council"},{"phrase":"local council"},{"phrase":"student council"},{"phrase":"council meeting"}]', NULL, '/ˈkaʊnsl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/counc/council__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 3, 'editor', 'biên tập viên; tổng biên tập', 'noun', '[{"en":"My sister works as an editor at a small publishing company.","vi":"Chị tôi làm biên tập viên ở một công ty xuất bản nhỏ."},{"en":"The editor asked me to cut the article to 500 words.","vi":"Biên tập viên yêu cầu tôi cắt bài báo xuống còn 500 chữ."},{"en":"He became the editor of the school newspaper in his final year.","vi":"Anh ấy trở thành tổng biên tập tờ báo trường vào năm cuối."}]', '[{"phrase":"newspaper editor"},{"phrase":"magazine editor"},{"phrase":"editor-in-chief"}]', NULL, '/ˈedɪtər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/edi/edito/editor__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 4, 'normally', 'thường thì; thông thường; bình thường', 'adverb', '[{"en":"I normally get up at six, but today I woke up late.","vi":"Tôi thường dậy lúc sáu giờ, nhưng hôm nay tôi dậy muộn."},{"en":"Normally, the trip takes about two hours by train.","vi":"Thông thường, chuyến đi mất khoảng hai tiếng bằng tàu hỏa."},{"en":"The doctor checked that the baby was breathing normally.","vi":"Bác sĩ kiểm tra xem em bé có thở bình thường không."}]', '[{"phrase":"breathe normally"},{"phrase":"function normally"},{"phrase":"behave normally"}]', NULL, '/ˈnɔːrməli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nor/norma/normally__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 5, 'sight', 'thị lực; cảnh tượng; tầm nhìn', 'noun', '[{"en":"My grandfather''s sight is getting worse, so he can''t drive.","vi":"Thị lực của ông tôi ngày càng kém nên ông không thể lái xe."},{"en":"The sunset over the sea was a beautiful sight.","vi":"Hoàng hôn trên biển là một cảnh tượng tuyệt đẹp."},{"en":"The children waved until the boat was out of sight.","vi":"Bọn trẻ vẫy tay cho đến khi con thuyền khuất tầm mắt."}]', '[{"phrase":"out of sight"},{"phrase":"at first sight"},{"phrase":"lose your sight"},{"phrase":"a beautiful sight"}]', 'sight (tầm nhìn) ≠ site (địa điểm)', '/saɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/sight/sight__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 6, 'generate', 'tạo ra; sinh ra', 'verb', '[{"en":"The new factory will generate hundreds of jobs for the town.","vi":"Nhà máy mới sẽ tạo ra hàng trăm việc làm cho thị trấn."},{"en":"Solar panels on the roof generate enough electricity for the house.","vi":"Các tấm pin mặt trời trên mái nhà tạo ra đủ điện cho cả ngôi nhà."},{"en":"Her idea generated a lot of interest at the meeting.","vi":"Ý tưởng của cô ấy đã thu hút nhiều sự quan tâm trong cuộc họp."}]', '[{"phrase":"generate electricity"},{"phrase":"generate income"},{"phrase":"generate interest"},{"phrase":"generate jobs"}]', NULL, '/ˈdʒenəreɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gener/generate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 7, 'gift', 'quà tặng; năng khiếu', 'noun', '[{"en":"Thank you so much for the lovely birthday gift.","vi":"Cảm ơn bạn rất nhiều vì món quà sinh nhật dễ thương."},{"en":"We bought a small gift for our neighbors before leaving.","vi":"Chúng tôi mua một món quà nhỏ tặng hàng xóm trước khi đi."},{"en":"She has a real gift for making people feel welcome.","vi":"Cô ấy thật sự có năng khiếu khiến mọi người cảm thấy được chào đón."}]', '[{"phrase":"birthday gift"},{"phrase":"wedding gift"},{"phrase":"gift shop"},{"phrase":"have a gift for"}]', NULL, '/ɡɪft/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gif/gift_/gift__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 8, 'delivery', 'sự giao hàng; sự phát (thư)', 'noun', '[{"en":"Delivery is free for orders over fifty dollars.","vi":"Miễn phí giao hàng cho đơn hàng trên năm mươi đô la."},{"en":"We''re still waiting for the delivery of our new fridge.","vi":"Chúng tôi vẫn đang chờ người ta giao chiếc tủ lạnh mới."},{"en":"The mail delivery was late because of the heavy snow.","vi":"Việc phát thư bị trễ do tuyết rơi dày."}]', '[{"phrase":"free delivery"},{"phrase":"home delivery"},{"phrase":"delivery date"},{"phrase":"mail delivery"}]', NULL, '/dɪˈlɪvəri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/del/deliv/delivery__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 9, 'deny', 'phủ nhận; chối; từ chối (cho)', 'verb', '[{"en":"He denied taking the money from the drawer.","vi":"Anh ta chối là đã lấy tiền trong ngăn kéo."},{"en":"The company strongly denies that its products are unsafe.","vi":"Công ty kiên quyết phủ nhận việc sản phẩm của họ không an toàn."},{"en":"She was denied entry because she had lost her passport.","vi":"Cô ấy bị từ chối cho nhập cảnh vì đã làm mất hộ chiếu."}]', '[{"phrase":"strongly deny"},{"phrase":"deny responsibility"},{"phrase":"deny access to"},{"phrase":"deny entry"}]', 'deny + V-ing: chối đã làm gì', '/dɪˈnaɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/den/deny_/deny__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 10, 'guest', 'khách; khách mời', 'noun', '[{"en":"We have guests coming for dinner tonight, so please tidy up.","vi":"Tối nay nhà mình có khách đến ăn tối, nên hãy dọn dẹp đi nhé."},{"en":"The hotel has a pool that is open to all guests.","vi":"Khách sạn có hồ bơi dành cho tất cả khách lưu trú."},{"en":"She was a guest speaker at our graduation ceremony.","vi":"Cô ấy là diễn giả khách mời trong lễ tốt nghiệp của chúng tôi."}]', '[{"phrase":"hotel guest"},{"phrase":"guest room"},{"phrase":"special guest"},{"phrase":"guest speaker"}]', NULL, '/ɡest/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gue/guest/guest__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 11, 'anybody', 'bất kỳ ai; ai (đó)', 'pronoun', '[{"en":"Is there anybody here who can speak Japanese?","vi":"Ở đây có ai nói được tiếng Nhật không?"},{"en":"I didn''t tell anybody about the surprise party.","vi":"Tôi không kể với ai về bữa tiệc bất ngờ."},{"en":"Anybody can learn to cook if they practice enough.","vi":"Bất kỳ ai cũng có thể học nấu ăn nếu luyện tập đủ nhiều."}]', '[{"phrase":"anybody else"},{"phrase":"hardly anybody"},{"phrase":"if anybody"}]', '= anyone', '/ˈenibɑːdi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/any/anybo/anybody__us_4_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 12, 'bedroom', 'phòng ngủ', 'noun', '[{"en":"Our apartment has two bedrooms and a small kitchen.","vi":"Căn hộ của chúng tôi có hai phòng ngủ và một căn bếp nhỏ."},{"en":"The kids are playing video games in their bedroom.","vi":"Bọn trẻ đang chơi trò chơi điện tử trong phòng ngủ."},{"en":"Can you close the bedroom window before you go to bed?","vi":"Bạn đóng cửa sổ phòng ngủ trước khi đi ngủ được không?"}]', '[{"phrase":"master bedroom"},{"phrase":"spare bedroom"},{"phrase":"bedroom window"},{"phrase":"two-bedroom apartment"}]', NULL, '/ˈbedruːm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bed/bedro/bedroom__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 13, 'quote', 'trích dẫn; báo giá', 'verb', '[{"en":"The article quotes a doctor who worked at the hospital.","vi":"Bài báo trích dẫn lời một bác sĩ từng làm việc tại bệnh viện."},{"en":"He often quotes lines from his favorite movies.","vi":"Anh ấy hay trích dẫn lời thoại trong những bộ phim mình yêu thích."},{"en":"The builder quoted us a price of two thousand dollars.","vi":"Người thợ xây báo giá cho chúng tôi hai nghìn đô la."}]', '[{"phrase":"quote a price"},{"phrase":"quote from"},{"phrase":"widely quoted"}]', NULL, '/kwəʊt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/quo/quote/quote__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 14, 'climb', 'leo; trèo; tăng lên', 'verb', '[{"en":"We climbed to the top of the hill to watch the sunrise.","vi":"Chúng tôi leo lên đỉnh đồi để ngắm bình minh."},{"en":"The cat climbed up the tree and wouldn''t come down.","vi":"Con mèo trèo lên cây và không chịu xuống."},{"en":"House prices have climbed steadily over the past five years.","vi":"Giá nhà đã tăng đều đặn trong năm năm qua."}]', '[{"phrase":"climb a mountain"},{"phrase":"climb the stairs"},{"phrase":"climb up"},{"phrase":"climb steadily"}]', NULL, '/klaɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cli/climb/climb__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 15, 'basically', 'về cơ bản; nói chung; thực chất', 'adverb', '[{"en":"Basically, we need more people to finish the project on time.","vi":"Về cơ bản, chúng ta cần thêm người để hoàn thành dự án đúng hạn."},{"en":"The two phones are basically the same, except for the color.","vi":"Hai chiếc điện thoại về cơ bản là giống nhau, chỉ khác màu sắc."},{"en":"He basically lives at his girlfriend''s place these days.","vi":"Dạo này thực chất anh ấy sống luôn ở nhà bạn gái."}]', '[{"phrase":"basically the same"},{"phrase":"basically true"},{"phrase":"basically right"}]', NULL, '/ˈbeɪsɪkli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bas/basic/basically__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 16, 'violence', 'bạo lực', 'noun', '[{"en":"There is too much violence in some children''s cartoons.","vi":"Có quá nhiều bạo lực trong một số phim hoạt hình dành cho trẻ em."},{"en":"The police are trying to stop the violence after the match.","vi":"Cảnh sát đang cố gắng ngăn chặn bạo lực sau trận đấu."},{"en":"Many schools teach students how to solve problems without violence.","vi":"Nhiều trường dạy học sinh cách giải quyết vấn đề mà không dùng bạo lực."}]', '[{"phrase":"act of violence"},{"phrase":"use violence"},{"phrase":"domestic violence"}]', 'không đếm được', '/ˈvaɪələns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vio/viole/violence__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 17, 'minister', 'bộ trưởng', 'noun', '[{"en":"The minister visited the new hospital on Monday morning.","vi":"Bộ trưởng đã đến thăm bệnh viện mới vào sáng thứ Hai."},{"en":"She became the youngest education minister in the country''s history.","vi":"Bà ấy trở thành bộ trưởng giáo dục trẻ nhất trong lịch sử đất nước."},{"en":"The health minister announced a plan to build more clinics.","vi":"Bộ trưởng Bộ Y tế công bố kế hoạch xây thêm phòng khám."}]', '[{"phrase":"prime minister"},{"phrase":"foreign minister"},{"phrase":"health minister"},{"phrase":"education minister"}]', 'prime minister: thủ tướng', '/ˈmɪnɪstər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/min/minis/minister__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 18, 'mainly', 'chủ yếu; phần lớn', 'adverb', '[{"en":"The people who come to this café are mainly students.","vi":"Những người đến quán cà phê này chủ yếu là sinh viên."},{"en":"I chose this apartment mainly because it''s close to work.","vi":"Tôi chọn căn hộ này chủ yếu vì nó gần chỗ làm."},{"en":"The weather will be mainly dry, with some rain in the evening.","vi":"Thời tiết phần lớn sẽ khô ráo, có một chút mưa vào buổi tối."}]', '[{"phrase":"mainly because"},{"phrase":"mainly due to"},{"phrase":"consist mainly of"}]', NULL, '/ˈmeɪnli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mai/mainl/mainly__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 19, 'mouth', 'miệng; cửa (sông)', 'noun', '[{"en":"Don''t talk with your mouth full, please.","vi":"Đừng nói chuyện khi miệng đang đầy thức ăn nhé."},{"en":"Open your mouth wide so I can look at your teeth.","vi":"Há miệng thật to để tôi xem răng của bạn nào."},{"en":"The town is at the mouth of the river.","vi":"Thị trấn nằm ở cửa sông."}]', '[{"phrase":"open your mouth"},{"phrase":"with your mouth full"},{"phrase":"mouth of the river"},{"phrase":"keep your mouth shut"}]', NULL, '/maʊθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mou/mouth/mouth__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 20, 'noise', 'tiếng ồn; tiếng động', 'noun', '[{"en":"I couldn''t sleep because of the noise from the street.","vi":"Tôi không ngủ được vì tiếng ồn ngoài đường."},{"en":"Please try not to make any noise; the baby is sleeping.","vi":"Cố gắng đừng gây tiếng động nhé, em bé đang ngủ."},{"en":"Did you hear that strange noise coming from the kitchen?","vi":"Bạn có nghe thấy tiếng động lạ phát ra từ trong bếp không?"}]', '[{"phrase":"make a noise"},{"phrase":"loud noise"},{"phrase":"background noise"},{"phrase":"strange noise"}]', NULL, '/nɔɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/noi/noise/noise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 21, 'manner', 'cách; thái độ; phép lịch sự', 'noun', '[{"en":"She answered the questions in a calm and friendly manner.","vi":"Cô ấy trả lời các câu hỏi một cách bình tĩnh và thân thiện."},{"en":"I didn''t like his manner; he seemed rude and impatient.","vi":"Tôi không thích thái độ của anh ta; anh ta có vẻ thô lỗ và thiếu kiên nhẫn."},{"en":"It''s bad manners to check your phone during dinner.","vi":"Xem điện thoại trong bữa tối là thiếu lịch sự."}]', '[{"phrase":"in a friendly manner"},{"phrase":"good manners"},{"phrase":"bad manners"}]', 'manners (số nhiều): phép lịch sự', '/ˈmænər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/man/manne/manner__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 22, 'gun', 'súng', 'noun', '[{"en":"The police officer carried a gun on his belt.","vi":"Viên cảnh sát đeo một khẩu súng bên thắt lưng."},{"en":"The kids had a water gun fight in the backyard.","vi":"Bọn trẻ đấu súng nước ở sân sau."},{"en":"The runners started as soon as they heard the gun.","vi":"Các vận động viên xuất phát ngay khi nghe tiếng súng."}]', '[{"phrase":"carry a gun"},{"phrase":"fire a gun"},{"phrase":"water gun"}]', NULL, '/ɡʌn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gun/gun__/gun__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 23, 'square', 'quảng trường; hình vuông', 'noun', '[{"en":"There is a small market in the town square every Saturday.","vi":"Có một phiên chợ nhỏ ở quảng trường thị trấn vào mỗi thứ Bảy."},{"en":"Cut the bread into small squares before serving.","vi":"Cắt bánh mì thành những miếng vuông nhỏ trước khi dọn ra."},{"en":"Draw a square and then divide it into four triangles.","vi":"Vẽ một hình vuông rồi chia nó thành bốn hình tam giác."}]', '[{"phrase":"town square"},{"phrase":"main square"},{"phrase":"draw a square"}]', NULL, '/skwer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/squ/squar/square__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 24, 'occasion', 'dịp; lần', 'noun', '[{"en":"We save this wine for special occasions like birthdays.","vi":"Chúng tôi để dành chai rượu vang này cho những dịp đặc biệt như sinh nhật."},{"en":"I''ve met her on several occasions, but we rarely talk.","vi":"Tôi đã gặp cô ấy vài lần, nhưng chúng tôi hiếm khi nói chuyện."},{"en":"The wedding was a happy occasion for the whole family.","vi":"Đám cưới là một dịp vui của cả gia đình."}]', '[{"phrase":"special occasion"},{"phrase":"on several occasions"},{"phrase":"on this occasion"}]', NULL, '/əˈkeɪʒn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/occ/occas/occasion__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 25, 'familiar', 'quen thuộc; am hiểu, rành', 'adjective', '[{"en":"Her face looks familiar, but I can''t remember her name.","vi":"Khuôn mặt cô ấy trông quen quen, nhưng tôi không nhớ tên cô ấy."},{"en":"Are you familiar with this part of the city?","vi":"Bạn có rành khu vực này của thành phố không?"},{"en":"It was nice to hear a familiar voice on the phone.","vi":"Thật vui khi nghe thấy một giọng nói quen thuộc qua điện thoại."}]', '[{"phrase":"look familiar"},{"phrase":"sound familiar"},{"phrase":"familiar face"},{"phrase":"familiar with"}]', 'be familiar with sth: quen / rành cái gì', '/fəˈmɪliər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fam/famil/familiar__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 26, 'ignore', 'phớt lờ; lờ đi; bỏ qua', 'verb', '[{"en":"She saw me wave but ignored me completely.","vi":"Cô ấy thấy tôi vẫy tay nhưng hoàn toàn phớt lờ tôi."},{"en":"You shouldn''t ignore the pain in your knee.","vi":"Bạn không nên bỏ qua cơn đau ở đầu gối."},{"en":"Just ignore him; he''s only trying to annoy you.","vi":"Cứ lờ anh ta đi, anh ta chỉ đang cố chọc tức bạn thôi."}]', '[{"phrase":"completely ignore"},{"phrase":"ignore advice"},{"phrase":"ignore a warning"},{"phrase":"ignore the problem"}]', NULL, '/ɪɡˈnɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ign/ignor/ignore__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 27, 'destroy', 'phá hủy; tàn phá; hủy hoại', 'verb', '[{"en":"A fire destroyed three houses on our street last night.","vi":"Đêm qua một vụ cháy đã thiêu rụi ba ngôi nhà trên phố chúng tôi."},{"en":"The storm completely destroyed the old wooden bridge.","vi":"Cơn bão đã phá hủy hoàn toàn cây cầu gỗ cũ."},{"en":"One bad review can destroy a small restaurant''s reputation.","vi":"Một đánh giá tệ có thể hủy hoại danh tiếng của một nhà hàng nhỏ."}]', '[{"phrase":"completely destroy"},{"phrase":"destroyed by fire"},{"phrase":"destroy the environment"}]', NULL, '/dɪˈstrɔɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/destr/destroy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 28, 'affair', 'việc; chuyện; sự kiện', 'noun', '[{"en":"How I spend my money is my own affair.","vi":"Tôi tiêu tiền thế nào là việc riêng của tôi."},{"en":"She enjoys reading about current affairs in the morning paper.","vi":"Cô ấy thích đọc tin thời sự trên báo buổi sáng."},{"en":"Their wedding was a small family affair in the garden.","vi":"Đám cưới của họ là một sự kiện nhỏ trong gia đình, tổ chức ngoài vườn."}]', '[{"phrase":"current affairs"},{"phrase":"foreign affairs"},{"phrase":"family affair"},{"phrase":"private affair"}]', 'current affairs: thời sự', '/əˈfer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aff/affai/affair__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 29, 'civil', 'dân sự; công dân; lịch sự', 'adjective', '[{"en":"Every citizen should understand their basic civil rights.","vi":"Mọi công dân nên hiểu các quyền công dân cơ bản của mình."},{"en":"My father worked as a civil servant for thirty years.","vi":"Bố tôi làm công chức nhà nước suốt ba mươi năm."},{"en":"Even when they argue, they stay civil to each other.","vi":"Ngay cả khi cãi nhau, họ vẫn lịch sự với nhau."}]', '[{"phrase":"civil rights"},{"phrase":"civil servant"},{"phrase":"civil engineer"}]', 'civil servant: công chức', '/ˈsɪvl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/civ/civil/civil__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-15', 30, 'locate', 'xác định vị trí; đặt ở', 'verb', '[{"en":"Our office is located on the third floor of the building.","vi":"Văn phòng của chúng tôi nằm ở tầng ba của tòa nhà."},{"en":"The hotel is conveniently located near the train station.","vi":"Khách sạn nằm ở vị trí thuận tiện gần ga tàu."},{"en":"This app helps you locate your phone if you lose it.","vi":"Ứng dụng này giúp bạn xác định vị trí điện thoại nếu bị mất."}]', '[{"phrase":"be located in"},{"phrase":"conveniently located"},{"phrase":"centrally located"}]', 'be located in/on/near: nằm ở', '/ˈləʊkeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loc/locat/locate__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-16', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 16', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 16);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 1, 'citizen', 'công dân', 'noun', '[{"en":"She became a citizen of Canada after living there for ten years.","vi":"Cô ấy trở thành công dân Canada sau khi sống ở đó mười năm."},{"en":"Every citizen has the right to vote in local elections.","vi":"Mọi công dân đều có quyền bỏ phiếu trong các cuộc bầu cử địa phương."},{"en":"Senior citizens can travel on city buses for free.","vi":"Người cao tuổi được đi xe buýt thành phố miễn phí."}]', '[{"phrase":"senior citizen"},{"phrase":"citizen of"},{"phrase":"ordinary citizens"},{"phrase":"fellow citizens"}]', NULL, '/ˈsɪtɪzn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cit/citiz/citizen__us_7.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 2, 'temperature', 'nhiệt độ', 'noun', '[{"en":"The temperature dropped below zero last night.","vi":"Đêm qua nhiệt độ đã xuống dưới không độ."},{"en":"The nurse took my temperature and said I had a slight fever.","vi":"Y tá đo nhiệt độ cho tôi và nói tôi hơi sốt."},{"en":"Bake the cake at a low temperature for about forty minutes.","vi":"Nướng bánh ở nhiệt độ thấp trong khoảng bốn mươi phút."}]', '[{"phrase":"high temperature"},{"phrase":"low temperature"},{"phrase":"room temperature"},{"phrase":"take someone''s temperature"}]', NULL, '/ˈtemprətʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tem/tempe/temperature__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 3, 'gold', 'vàng', 'noun', '[{"en":"She wore a thin chain made of gold.","vi":"Cô ấy đeo một sợi dây chuyền mảnh làm bằng vàng."},{"en":"The price of gold has risen sharply this year.","vi":"Giá vàng đã tăng mạnh trong năm nay."},{"en":"Our team won the gold medal in the relay race.","vi":"Đội chúng tôi đã giành huy chương vàng ở môn chạy tiếp sức."}]', '[{"phrase":"made of gold"},{"phrase":"price of gold"},{"phrase":"gold medal"},{"phrase":"solid gold"}]', 'không đếm được', '/ɡəʊld/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gol/gold_/gold__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 4, 'domestic', 'trong nước, nội địa; (thuộc) gia đình', 'adjective', '[{"en":"Domestic flights are usually cheaper than international ones.","vi":"Các chuyến bay nội địa thường rẻ hơn các chuyến bay quốc tế."},{"en":"The company sells most of its products in the domestic market.","vi":"Công ty bán phần lớn sản phẩm của mình ở thị trường trong nước."},{"en":"My parents shared domestic tasks like cooking and cleaning.","vi":"Bố mẹ tôi chia nhau làm việc nhà như nấu ăn và dọn dẹp."}]', '[{"phrase":"domestic flights"},{"phrase":"domestic market"},{"phrase":"domestic animals"}]', NULL, '/dəˈmestɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dom/domes/domestic__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 5, 'load', 'hàng chở; khối lượng (công việc)', 'noun', '[{"en":"The small boat could not carry such a heavy load.","vi":"Chiếc thuyền nhỏ không thể chở hàng nặng như vậy."},{"en":"The workers took turns carrying loads of sand up the hill.","vi":"Các công nhân thay phiên nhau khuân những bao cát lên đồi."},{"en":"She has a heavy teaching load this semester.","vi":"Học kỳ này cô ấy có khối lượng giảng dạy nặng."}]', '[{"phrase":"heavy load"},{"phrase":"carry a load"},{"phrase":"teaching load"}]', NULL, '/ləʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/loa/load_/load__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 6, 'belief', 'niềm tin; quan niệm', 'noun', '[{"en":"They have a strong belief in the value of education.","vi":"Họ có niềm tin mạnh mẽ vào giá trị của giáo dục."},{"en":"It is a common belief that carrots improve your eyesight.","vi":"Nhiều người vẫn tin rằng cà rốt giúp mắt nhìn tốt hơn."},{"en":"Contrary to popular belief, bats are not blind.","vi":"Trái với quan niệm phổ biến, loài dơi không hề bị mù."}]', '[{"phrase":"strong belief"},{"phrase":"belief in"},{"phrase":"common belief"},{"phrase":"popular belief"}]', NULL, '/bɪˈliːf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bel/belie/belief__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 7, 'troop', 'quân lính; đoàn, nhóm', 'noun', '[{"en":"The army sent troops to help people after the flood.","vi":"Quân đội đã điều binh lính đến giúp người dân sau trận lụt."},{"en":"Hundreds of troops helped clear the roads after the storm.","vi":"Hàng trăm binh lính đã giúp dọn đường sau cơn bão."},{"en":"A troop of scouts camped by the lake last weekend.","vi":"Một đoàn hướng đạo sinh đã cắm trại bên hồ vào cuối tuần trước."}]', '[{"phrase":"send troops"},{"phrase":"a troop of"}]', 'thường dùng số nhiều: troops (quân lính)', '/truːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tro/troop/troop__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 8, 'technical', '(thuộc) kỹ thuật; chuyên môn', 'adjective', '[{"en":"Please call our support team if you have any technical problems.","vi":"Vui lòng gọi cho đội hỗ trợ nếu bạn gặp bất kỳ sự cố kỹ thuật nào."},{"en":"He studied at a technical college before becoming an engineer.","vi":"Anh ấy học ở một trường cao đẳng kỹ thuật trước khi trở thành kỹ sư."},{"en":"The article was too technical for most readers to understand.","vi":"Bài báo quá nặng chuyên môn nên hầu hết người đọc không hiểu được."}]', '[{"phrase":"technical problems"},{"phrase":"technical support"},{"phrase":"technical skills"},{"phrase":"technical terms"}]', NULL, '/ˈteknɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tec/techn/technical__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 9, 'remind', 'nhắc nhở; gợi nhớ', 'verb', '[{"en":"Can you remind me to call my mother tonight?","vi":"Bạn nhắc tôi gọi cho mẹ tối nay được không?"},{"en":"The teacher reminded the students that the test was on Friday.","vi":"Cô giáo nhắc học sinh rằng bài kiểm tra vào thứ Sáu."},{"en":"This song always reminds me of our trip to the beach.","vi":"Bài hát này luôn gợi cho tôi nhớ về chuyến đi biển của chúng ta."}]', '[{"phrase":"remind someone to"},{"phrase":"remind someone of"},{"phrase":"remind me"}]', 'remind sb to do sth (nhắc) · remind sb of sth (gợi nhớ)', '/rɪˈmaɪnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rem/remin/remind__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 10, 'arrangement', 'sự sắp xếp; sự chuẩn bị; sự thỏa thuận', 'noun', '[{"en":"She liked the new arrangement of furniture in the living room.","vi":"Cô ấy thích cách sắp xếp đồ đạc mới trong phòng khách."},{"en":"We need to make arrangements for the wedding soon.","vi":"Chúng tôi cần sớm lo chuẩn bị cho đám cưới."},{"en":"They have an arrangement to share the car on weekdays.","vi":"Họ có thỏa thuận dùng chung xe vào các ngày trong tuần."}]', '[{"phrase":"make arrangements"},{"phrase":"travel arrangements"},{"phrase":"flower arrangement"}]', NULL, '/əˈreɪndʒmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arr/arran/arrangement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 11, 'skin', 'da; vỏ', 'noun', '[{"en":"This cream helps keep dry skin soft in cold weather.","vi":"Loại kem này giúp da khô luôn mềm mại khi trời lạnh."},{"en":"Wear sunscreen to protect your skin from the sun.","vi":"Hãy bôi kem chống nắng để bảo vệ da khỏi ánh nắng."},{"en":"Peel the skin off the potatoes before you boil them.","vi":"Gọt vỏ khoai tây trước khi luộc."}]', '[{"phrase":"dry skin"},{"phrase":"sensitive skin"},{"phrase":"skin care"}]', NULL, '/skɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ski/skin_/skin__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 12, 'prison', 'nhà tù', 'noun', '[{"en":"He spent two years in prison for stealing cars.","vi":"Anh ta đã ngồi tù hai năm vì tội trộm xe hơi."},{"en":"The old prison has been turned into a museum.","vi":"Nhà tù cũ đã được biến thành bảo tàng."},{"en":"The judge sent him to prison for five years.","vi":"Thẩm phán đã kết án anh ta năm năm tù."}]', '[{"phrase":"in prison"},{"phrase":"go to prison"},{"phrase":"prison sentence"},{"phrase":"send someone to prison"}]', NULL, '/ˈprɪzn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pri/priso/prison__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 13, 'switch', 'chuyển, đổi; bật, tắt', 'verb', '[{"en":"I switched to a new phone company because it was cheaper.","vi":"Tôi đã chuyển sang nhà mạng mới vì giá rẻ hơn."},{"en":"Can we switch seats so I can sit by the window?","vi":"Chúng ta đổi chỗ được không để tôi ngồi cạnh cửa sổ?"},{"en":"Please switch off the lights when you leave the room.","vi":"Vui lòng tắt đèn khi rời khỏi phòng."}]', '[{"phrase":"switch off"},{"phrase":"switch on"},{"phrase":"switch to"}]', 'switch on = bật · switch off = tắt', '/swɪtʃ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/swi/switc/switch__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 14, 'acquire', 'có được, tiếp thu; mua lại', 'verb', '[{"en":"Students acquire knowledge best when they enjoy what they learn.","vi":"Học sinh tiếp thu kiến thức tốt nhất khi các em thích điều mình học."},{"en":"Children acquire language quickly by listening to people around them.","vi":"Trẻ em tiếp thu ngôn ngữ nhanh nhờ lắng nghe những người xung quanh."},{"en":"The large company acquired a small software firm last year.","vi":"Năm ngoái, công ty lớn đó đã mua lại một công ty phần mềm nhỏ."}]', '[{"phrase":"acquire knowledge"},{"phrase":"acquire skills"},{"phrase":"acquire a company"}]', NULL, '/əˈkwaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/acq/acqui/acquire__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 15, 'corporate', '(thuộc) công ty, doanh nghiệp', 'adjective', '[{"en":"He left the corporate world to open a small café.","vi":"Anh ấy rời bỏ môi trường doanh nghiệp để mở một quán cà phê nhỏ."},{"en":"Our corporate office is located in the city center.","vi":"Trụ sở công ty chúng tôi nằm ở trung tâm thành phố."},{"en":"Many banks offer special accounts for corporate customers.","vi":"Nhiều ngân hàng có tài khoản đặc biệt dành cho khách hàng doanh nghiệp."}]', '[{"phrase":"corporate world"},{"phrase":"corporate culture"},{"phrase":"corporate clients"}]', NULL, '/ˈkɔːrpərət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cor/corpo/corporate__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 16, 'fairly', 'khá; một cách công bằng', 'adverb', '[{"en":"The hotel room was fairly small but very clean.","vi":"Phòng khách sạn khá nhỏ nhưng rất sạch sẽ."},{"en":"I speak French fairly well, but my writing is poor.","vi":"Tôi nói tiếng Pháp khá tốt, nhưng viết thì kém."},{"en":"The manager promised to treat all workers fairly.","vi":"Người quản lý hứa sẽ đối xử công bằng với tất cả nhân viên."}]', '[{"phrase":"fairly well"},{"phrase":"fairly easy"},{"phrase":"fairly common"},{"phrase":"treat someone fairly"}]', NULL, '/ˈferli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fai/fairl/fairly__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 17, 'wood', 'gỗ; rừng (the woods)', 'noun', '[{"en":"The table is made of solid wood.","vi":"Chiếc bàn được làm bằng gỗ nguyên khối."},{"en":"We collected wood to make a fire at the campsite.","vi":"Chúng tôi nhặt củi để nhóm lửa ở khu cắm trại."},{"en":"They went for a walk in the woods behind their house.","vi":"Họ đi dạo trong khu rừng phía sau nhà."}]', '[{"phrase":"made of wood"},{"phrase":"piece of wood"},{"phrase":"in the woods"}]', 'the woods = khu rừng nhỏ', '/wʊd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/woo/wood_/wood__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 18, 'participate', 'tham gia', 'verb', '[{"en":"All students are expected to participate in class discussions.","vi":"Tất cả học sinh đều được yêu cầu tham gia thảo luận trên lớp."},{"en":"More than fifty companies participated in the job fair.","vi":"Hơn năm mươi công ty đã tham gia hội chợ việc làm."},{"en":"Would you like to participate in our short online survey?","vi":"Bạn có muốn tham gia khảo sát trực tuyến ngắn của chúng tôi không?"}]', '[{"phrase":"participate in"},{"phrase":"actively participate"},{"phrase":"participate fully"}]', 'participate in sth', '/pɑːrˈtɪsɪpeɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/par/parti/participate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 19, 'tough', 'khó khăn; cứng rắn; dai', 'adjective', '[{"en":"It was a tough decision, but we chose to move abroad.","vi":"Đó là một quyết định khó khăn, nhưng chúng tôi đã chọn ra nước ngoài sống."},{"en":"My boss is tough but always fair to everyone.","vi":"Sếp tôi nghiêm khắc nhưng luôn công bằng với mọi người."},{"en":"The steak was too tough to cut with a normal knife.","vi":"Miếng bít tết dai quá, không cắt được bằng dao thường."}]', '[{"phrase":"tough decision"},{"phrase":"tough time"},{"phrase":"tough question"}]', NULL, '/tʌf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tou/tough/tough__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 20, 'tear', 'nước mắt', 'noun', '[{"en":"Tears ran down her face as she read the letter.","vi":"Nước mắt lăn dài trên má cô ấy khi đọc lá thư."},{"en":"The little boy burst into tears when he dropped his ice cream.","vi":"Cậu bé òa khóc khi làm rơi cây kem."},{"en":"By the end of the movie, we were all in tears.","vi":"Đến cuối phim, tất cả chúng tôi đều rơi nước mắt."}]', '[{"phrase":"burst into tears"},{"phrase":"in tears"},{"phrase":"tears of joy"},{"phrase":"hold back tears"}]', 'tear (n) /tɪə/ nước mắt ≠ tear (v) /teə/ xé', '/ter/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tea/tear_/tear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 21, 'representative', 'người đại diện; đại biểu', 'noun', '[{"en":"Each class chose a representative to attend the school meeting.","vi":"Mỗi lớp chọn một người đại diện để dự cuộc họp của trường."},{"en":"A representative from the bank will call you tomorrow.","vi":"Ngày mai một người đại diện của ngân hàng sẽ gọi cho bạn."},{"en":"She was elected student representative for her university.","vi":"Cô ấy được bầu làm đại diện sinh viên của trường đại học."}]', '[{"phrase":"sales representative"},{"phrase":"elected representative"},{"phrase":"representative from"}]', NULL, '/ˌreprɪˈzentətɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rep/repre/representative__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 22, 'capacity', 'sức chứa; khả năng, năng lực', 'noun', '[{"en":"The stadium has a capacity of fifty thousand people.","vi":"Sân vận động có sức chứa năm mươi nghìn người."},{"en":"The concert hall was filled to capacity last night.","vi":"Tối qua phòng hòa nhạc chật kín người."},{"en":"Some children have a great capacity for learning languages.","vi":"Một số trẻ có khả năng học ngoại ngữ rất tốt."}]', '[{"phrase":"filled to capacity"},{"phrase":"full capacity"},{"phrase":"seating capacity"},{"phrase":"capacity for"}]', NULL, '/kəˈpæsəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cap/capac/capacity__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 23, 'border', 'biên giới; đường viền', 'noun', '[{"en":"You need a passport to cross the border.","vi":"Bạn cần hộ chiếu để qua biên giới."},{"en":"The town is just a few kilometers from the border.","vi":"Thị trấn chỉ cách biên giới vài ki-lô-mét."},{"en":"The white plate has a thin blue border around the edge.","vi":"Chiếc đĩa trắng có một đường viền xanh mảnh quanh mép."}]', '[{"phrase":"cross the border"},{"phrase":"border crossing"},{"phrase":"along the border"}]', NULL, '/ˈbɔːrdər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bor/borde/border__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 24, 'shake', 'lắc; rung; bắt tay (shake hands)', 'verb', '[{"en":"Don''t just shake your head; tell me what you think.","vi":"Đừng chỉ lắc đầu, hãy nói cho tôi biết bạn nghĩ gì."},{"en":"The windows shook when the big truck drove past.","vi":"Cửa sổ rung lên khi chiếc xe tải lớn chạy qua."},{"en":"They shook hands and agreed to work together.","vi":"Họ bắt tay và đồng ý hợp tác với nhau."}]', '[{"phrase":"shake your head"},{"phrase":"shake hands"},{"phrase":"shake well"}]', 'shake – shook – shaken', '/ʃeɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/shake/shake__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 25, 'assessment', 'sự đánh giá', 'noun', '[{"en":"The final assessment will be based on your project and exam.","vi":"Kết quả đánh giá cuối kỳ sẽ dựa trên dự án và bài thi của bạn."},{"en":"Doctors made a careful assessment of her health before surgery.","vi":"Các bác sĩ đã đánh giá kỹ sức khỏe của cô ấy trước ca phẫu thuật."},{"en":"The bank carried out a risk assessment before lending the money.","vi":"Ngân hàng đã tiến hành đánh giá rủi ro trước khi cho vay tiền."}]', '[{"phrase":"risk assessment"},{"phrase":"careful assessment"},{"phrase":"carry out an assessment"}]', NULL, '/əˈsesmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/asses/assessment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 26, 'shoe', 'giày', 'noun', '[{"en":"I need a new pair of shoes for work.","vi":"Tôi cần một đôi giày mới để đi làm."},{"en":"Please take off your shoes before you enter the house.","vi":"Vui lòng cởi giày trước khi vào nhà."},{"en":"These running shoes are very comfortable for long walks.","vi":"Đôi giày chạy bộ này rất thoải mái khi đi bộ đường dài."}]', '[{"phrase":"pair of shoes"},{"phrase":"running shoes"},{"phrase":"take off your shoes"}]', NULL, '/ʃuː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shoe_/shoe__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 27, 'ought', 'nên; lẽ ra phải', 'verb', '[{"en":"You ought to see a doctor about that cough.","vi":"Bạn nên đi khám bác sĩ về cơn ho đó."},{"en":"We ought to leave now or we will miss the train.","vi":"Chúng ta nên đi ngay bây giờ, không thì sẽ lỡ tàu."},{"en":"They ought to have told us about the change earlier.","vi":"Lẽ ra họ phải báo cho chúng tôi về sự thay đổi sớm hơn."}]', '[{"phrase":"ought to"},{"phrase":"ought not to"},{"phrase":"ought to have"}]', 'luôn đi với to: ought to + V nguyên mẫu', '/ˈɔt/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 28, 'ad', 'quảng cáo', 'noun', '[{"en":"I saw an ad for a cheap apartment online.","vi":"Tôi thấy trên mạng một quảng cáo về căn hộ giá rẻ."},{"en":"The company spent a lot of money on TV ads.","vi":"Công ty đã chi rất nhiều tiền cho quảng cáo trên truyền hình."},{"en":"She put an ad in the newspaper to sell her old bike.","vi":"Cô ấy đăng quảng cáo trên báo để bán chiếc xe đạp cũ."}]', '[{"phrase":"TV ad"},{"phrase":"online ad"},{"phrase":"put an ad in"}]', 'viết tắt của advertisement', '/æd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ad_/ad__u/ad__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 29, 'fee', 'phí, lệ phí', 'noun', '[{"en":"School fees at private schools rise every year.","vi":"Học phí ở các trường tư tăng mỗi năm."},{"en":"There is no entrance fee for children under six.","vi":"Trẻ em dưới sáu tuổi được miễn phí vào cửa."},{"en":"The bank charges a small fee for each transfer.","vi":"Ngân hàng thu một khoản phí nhỏ cho mỗi lần chuyển tiền."}]', '[{"phrase":"school fees"},{"phrase":"entrance fee"},{"phrase":"charge a fee"},{"phrase":"membership fee"}]', NULL, '/fiː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fee/fee__/fee__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-16', 30, 'hall', 'hội trường; hành lang', 'noun', '[{"en":"The wedding reception was held in a large hall.","vi":"Tiệc cưới được tổ chức trong một hội trường lớn."},{"en":"The students gathered in the school hall for the meeting.","vi":"Học sinh tập trung ở hội trường của trường để dự buổi họp."},{"en":"Her office is at the end of the hall on the left.","vi":"Văn phòng của cô ấy ở cuối hành lang, bên trái."}]', '[{"phrase":"concert hall"},{"phrase":"town hall"},{"phrase":"school hall"},{"phrase":"sports hall"}]', NULL, '/hɔːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hal/hall_/hall__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-3-17', 'ngsl-3', 'Thông dụng 1.001–1.500 · Bộ 17', 'New General Service List, thứ hạng 1.001–1.500', '#3da9fc', 'BookOpen', 17);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 1, 'regulation', 'quy định; điều lệ', 'noun', '[{"en":"Safety regulations require all workers to wear helmets on site.","vi":"Các quy định an toàn yêu cầu mọi công nhân phải đội mũ bảo hộ tại công trường."},{"en":"The company broke several regulations and had to pay a fine.","vi":"Công ty đã vi phạm một số quy định và phải nộp phạt."},{"en":"New regulations on smoking in public places start next month.","vi":"Các quy định mới về hút thuốc ở nơi công cộng sẽ bắt đầu áp dụng từ tháng sau."}]', '[{"phrase":"safety regulations"},{"phrase":"new regulations"},{"phrase":"follow regulations"},{"phrase":"strict regulations"}]', NULL, '/ˌreɡjuˈleɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regul/regulation__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 2, 'escape', 'thoát khỏi; trốn thoát', 'verb', '[{"en":"The bird escaped from its cage when I opened the door.","vi":"Con chim đã thoát khỏi lồng khi tôi mở cửa."},{"en":"Two prisoners escaped from the prison last night.","vi":"Hai tù nhân đã trốn khỏi nhà tù tối qua."},{"en":"We went to the countryside to escape the noise of the city.","vi":"Chúng tôi về vùng quê để thoát khỏi sự ồn ào của thành phố."}]', '[{"phrase":"escape from prison"},{"phrase":"try to escape"},{"phrase":"narrowly escape"}]', NULL, '/ɪˈskeɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/esc/escap/escape__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 3, 'studio', 'phòng thu; xưởng vẽ; căn hộ một phòng', 'noun', '[{"en":"The band spent three months recording the album in a studio.","vi":"Ban nhạc đã dành ba tháng thu âm album trong phòng thu."},{"en":"My aunt paints in a small studio behind her house.","vi":"Dì tôi vẽ tranh trong một xưởng vẽ nhỏ phía sau nhà."},{"en":"He rents a studio apartment near the university.","vi":"Anh ấy thuê một căn hộ một phòng gần trường đại học."}]', '[{"phrase":"recording studio"},{"phrase":"television studio"},{"phrase":"studio apartment"}]', NULL, '/ˈstuːdiəʊ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/stu/studi/studio__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 4, 'proper', 'đúng; thích hợp; tử tế, ra hồn', 'adjective', '[{"en":"Please put the books back in their proper place.","vi":"Vui lòng để sách lại đúng chỗ của chúng."},{"en":"You need proper shoes for walking in the mountains.","vi":"Bạn cần giày thích hợp để đi bộ trên núi."},{"en":"I haven''t had a proper meal all day.","vi":"Cả ngày nay tôi chưa được ăn một bữa ra hồn."}]', '[{"phrase":"proper place"},{"phrase":"proper training"},{"phrase":"proper meal"},{"phrase":"the proper way"}]', NULL, '/ˈprɑːpər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/prope/proper__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 5, 'relax', 'thư giãn; thả lỏng', 'verb', '[{"en":"I like to relax with a good book after work.","vi":"Tôi thích thư giãn với một cuốn sách hay sau giờ làm."},{"en":"Just relax and take a deep breath before you start.","vi":"Cứ thả lỏng và hít một hơi thật sâu trước khi bắt đầu."},{"en":"We relaxed on the beach for the whole afternoon.","vi":"Chúng tôi thư giãn trên bãi biển suốt cả buổi chiều."}]', '[{"phrase":"try to relax"},{"phrase":"relax at home"},{"phrase":"relax your muscles"}]', NULL, '/rɪˈlæks/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relax/relax__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 6, 'tourist', 'khách du lịch, du khách', 'noun', '[{"en":"The old town is full of tourists in the summer.","vi":"Vào mùa hè, phố cổ đông nghịt khách du lịch."},{"en":"A tourist asked me for directions to the train station.","vi":"Một du khách hỏi tôi đường đến ga tàu."},{"en":"The waterfall has become a popular tourist attraction.","vi":"Thác nước đã trở thành một điểm du lịch được nhiều người yêu thích."}]', '[{"phrase":"tourist attraction"},{"phrase":"foreign tourists"},{"phrase":"tourist information"}]', NULL, '/ˈtʊrɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tou/touri/tourist__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 7, 'component', 'thành phần; linh kiện, bộ phận', 'noun', '[{"en":"The factory makes components for cars and trucks.","vi":"Nhà máy sản xuất linh kiện cho ô tô và xe tải."},{"en":"Trust is an important component of any relationship.","vi":"Sự tin tưởng là một thành phần quan trọng của mọi mối quan hệ."},{"en":"One broken component can stop the whole machine from working.","vi":"Chỉ một bộ phận bị hỏng cũng có thể khiến cả cỗ máy ngừng hoạt động."}]', '[{"phrase":"key component"},{"phrase":"important component"},{"phrase":"electronic components"}]', NULL, '/kəmˈpəʊnənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compo/component__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 8, 'afford', 'có đủ tiền (mua, trả); đủ sức (làm gì)', 'verb', '[{"en":"We can''t afford a new car this year.","vi":"Năm nay chúng tôi không có đủ tiền mua xe mới."},{"en":"She couldn''t afford to lose her job right now.","vi":"Lúc này cô ấy không thể để mất việc được."},{"en":"Many young people can hardly afford the rent in big cities.","vi":"Nhiều người trẻ khó mà trả nổi tiền thuê nhà ở các thành phố lớn."}]', '[{"phrase":"can''t afford"},{"phrase":"afford to pay"},{"phrase":"afford to lose"}]', 'thường đi với can/could: can’t afford (to do) sth', '/əˈfɔːrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aff/affor/afford__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 9, 'lawyer', 'luật sư', 'noun', '[{"en":"You should talk to a lawyer before signing the contract.","vi":"Bạn nên nói chuyện với luật sư trước khi ký hợp đồng."},{"en":"Her father has worked as a lawyer for twenty years.","vi":"Bố cô ấy đã làm luật sư được hai mươi năm."},{"en":"My lawyer said we had a good chance of winning.","vi":"Luật sư của tôi nói chúng tôi có nhiều khả năng thắng."}]', '[{"phrase":"hire a lawyer"},{"phrase":"consult a lawyer"},{"phrase":"defense lawyer"}]', NULL, '/ˈlɔɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/law/lawye/lawyer__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 10, 'suspect', 'nghi ngờ; ngờ rằng', 'verb', '[{"en":"I suspect he forgot about our meeting again.","vi":"Tôi ngờ là anh ấy lại quên cuộc họp của chúng ta rồi."},{"en":"Police suspect that the fire was started on purpose.","vi":"Cảnh sát nghi ngờ vụ cháy là do có người cố ý gây ra."},{"en":"Nobody suspected the quiet neighbor of stealing the money.","vi":"Không ai nghi ngờ người hàng xóm ít nói đã lấy trộm tiền."}]', '[{"phrase":"strongly suspect"},{"phrase":"suspect somebody of something"}]', 'suspect sb of sth: nghi ai làm gì · (n) suspect: nghi phạm', '/səˈspekt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sus/suspe/suspect__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 11, 'cup', 'tách, cốc; cúp (giải thưởng)', 'noun', '[{"en":"Would you like a cup of tea before we start?","vi":"Bạn có muốn uống một tách trà trước khi chúng ta bắt đầu không?"},{"en":"She drinks two cups of coffee every morning.","vi":"Sáng nào cô ấy cũng uống hai tách cà phê."},{"en":"Our school team won the cup for the first time.","vi":"Đội của trường chúng tôi lần đầu tiên giành được cúp."}]', '[{"phrase":"cup of tea"},{"phrase":"cup of coffee"},{"phrase":"paper cup"},{"phrase":"win the cup"}]', NULL, '/kʌp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cup/cup__/cup__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 12, 'description', 'sự mô tả; bản mô tả', 'noun', '[{"en":"Can you give me a description of the man you saw?","vi":"Bạn có thể mô tả cho tôi người đàn ông mà bạn đã thấy không?"},{"en":"The job description says you need two years of experience.","vi":"Bản mô tả công việc ghi rằng bạn cần có hai năm kinh nghiệm."},{"en":"The hotel looked exactly like the description on the website.","vi":"Khách sạn trông đúng y như phần mô tả trên trang web."}]', '[{"phrase":"give a description"},{"phrase":"job description"},{"phrase":"detailed description"},{"phrase":"brief description"}]', NULL, '/dɪˈskrɪpʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/des/descr/description__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 13, 'confidence', 'sự tự tin; sự tin tưởng', 'noun', '[{"en":"Speaking in front of the class helped her build confidence.","vi":"Việc phát biểu trước lớp đã giúp cô ấy rèn luyện sự tự tin."},{"en":"He answered every question in the interview with confidence.","vi":"Anh ấy tự tin trả lời mọi câu hỏi trong buổi phỏng vấn."},{"en":"I have complete confidence in my team.","vi":"Tôi hoàn toàn tin tưởng vào đội của mình."}]', '[{"phrase":"build confidence"},{"phrase":"lack of confidence"},{"phrase":"have confidence in"},{"phrase":"lose confidence"}]', 'confidence in sb/sth: tin tưởng vào ai/cái gì', '/ˈkɑːnfɪdəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfidence__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 14, 'industrial', '(thuộc) công nghiệp', 'adjective', '[{"en":"There is a large industrial area just outside the town.","vi":"Có một khu công nghiệp lớn ngay bên ngoài thị trấn."},{"en":"Industrial waste has polluted the river for many years.","vi":"Chất thải công nghiệp đã làm ô nhiễm dòng sông trong nhiều năm."},{"en":"They turned an old industrial building into a coffee shop.","vi":"Họ đã biến một nhà xưởng cũ thành quán cà phê."}]', '[{"phrase":"industrial area"},{"phrase":"industrial waste"},{"phrase":"industrial production"}]', NULL, '/ɪnˈdʌstriəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ind/indus/industrial__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 15, 'complain', 'phàn nàn, than phiền; khiếu nại', 'verb', '[{"en":"My neighbors complained about the noise from our party.","vi":"Hàng xóm đã phàn nàn về tiếng ồn từ bữa tiệc của chúng tôi."},{"en":"He''s always complaining that he has too much work.","vi":"Anh ấy lúc nào cũng than phiền rằng mình có quá nhiều việc."},{"en":"If the food is cold, you should complain to the manager.","vi":"Nếu đồ ăn bị nguội, bạn nên khiếu nại với quản lý."}]', '[{"phrase":"complain about"},{"phrase":"complain to somebody"},{"phrase":"constantly complain"}]', 'complain about sth / to sb', '/kəmˈpleɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compl/complain__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 16, 'perspective', 'góc nhìn; quan điểm', 'noun', '[{"en":"Living abroad gave me a new perspective on my own culture.","vi":"Sống ở nước ngoài đã cho tôi một góc nhìn mới về văn hóa của chính mình."},{"en":"Try to see the problem from your customer''s perspective.","vi":"Hãy thử nhìn vấn đề từ góc nhìn của khách hàng."},{"en":"Talking to friends helped me put my worries into perspective.","vi":"Nói chuyện với bạn bè giúp tôi nhìn nhận những lo lắng của mình một cách đúng mức hơn."}]', '[{"phrase":"new perspective"},{"phrase":"from a different perspective"},{"phrase":"put things into perspective"}]', NULL, '/pərˈspektɪv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/per/persp/perspective__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 17, 'error', 'lỗi; sai sót', 'noun', '[{"en":"There are a few spelling errors in your report.","vi":"Có vài lỗi chính tả trong bản báo cáo của bạn."},{"en":"The accident was caused by human error.","vi":"Vụ tai nạn là do lỗi của con người."},{"en":"I made an error when I added up the bill.","vi":"Tôi đã mắc sai sót khi cộng tiền hóa đơn."}]', '[{"phrase":"make an error"},{"phrase":"human error"},{"phrase":"spelling error"},{"phrase":"error message"}]', NULL, '/ˈerər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/err/error/error__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 18, 'arrest', 'bắt giữ', 'verb', '[{"en":"Police arrested two men outside the bank last night.","vi":"Tối qua cảnh sát đã bắt giữ hai người đàn ông bên ngoài ngân hàng."},{"en":"He was arrested for driving without a license.","vi":"Anh ta bị bắt vì lái xe không có bằng."},{"en":"The thief was arrested a few hours after the robbery.","vi":"Tên trộm đã bị bắt vài giờ sau vụ cướp."}]', '[{"phrase":"arrest a suspect"},{"phrase":"be arrested for"},{"phrase":"under arrest"}]', 'arrest sb for sth · (n) under arrest: bị bắt giữ', '/əˈrest/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/arr/arres/arrest__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 19, 'assess', 'đánh giá', 'verb', '[{"en":"Teachers assess students'' progress at the end of each term.","vi":"Giáo viên đánh giá sự tiến bộ của học sinh vào cuối mỗi học kỳ."},{"en":"Doctors need to assess how serious the injury is.","vi":"Các bác sĩ cần đánh giá mức độ nghiêm trọng của vết thương."},{"en":"It''s hard to assess the damage until the water goes down.","vi":"Khó mà đánh giá được thiệt hại cho đến khi nước rút."}]', '[{"phrase":"assess the damage"},{"phrase":"assess the situation"},{"phrase":"carefully assess"}]', NULL, '/əˈses/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/asses/assess__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-3-17', 20, 'register', 'đăng ký', 'verb', '[{"en":"You need to register online before the course begins.","vi":"Bạn cần đăng ký trực tuyến trước khi khóa học bắt đầu."},{"en":"Have you registered your new car yet?","vi":"Bạn đã đăng ký chiếc xe mới của mình chưa?"},{"en":"More than two hundred people registered for the conference.","vi":"Hơn hai trăm người đã đăng ký tham dự hội nghị."}]', '[{"phrase":"register for a course"},{"phrase":"register online"},{"phrase":"register a birth"}]', NULL, '/ˈredʒɪstər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regis/register__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-4-01', 'ngsl-4', 'Thông dụng 1.501–2.000 · Bộ 1', 'New General Service List, thứ hạng 1.501–2.000', '#3da9fc', 'BookOpen', 1);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 1, 'asset', 'tài sản; lợi thế, người/vật có giá trị', 'noun', '[{"en":"The company sold some of its assets to pay its debts.","vi":"Công ty đã bán một số tài sản để trả nợ."},{"en":"Their house is the most valuable asset they own.","vi":"Ngôi nhà là tài sản có giá trị nhất mà họ sở hữu."},{"en":"Her friendly personality is a real asset in this job.","vi":"Tính cách thân thiện của cô ấy là một lợi thế thực sự trong công việc này."}]', '[{"phrase":"valuable asset"},{"phrase":"financial assets"},{"phrase":"a great asset"},{"phrase":"an asset to the team"}]', NULL, '/ˈæset/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ass/asset/asset__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 2, 'signal', 'tín hiệu; dấu hiệu', 'noun', '[{"en":"I can''t call you because there''s no signal here.","vi":"Tôi không gọi cho bạn được vì ở đây không có sóng."},{"en":"The teacher gave us a signal to start writing.","vi":"Cô giáo ra hiệu cho chúng tôi bắt đầu viết."},{"en":"Feeling tired all the time can be a warning signal.","vi":"Lúc nào cũng thấy mệt có thể là một dấu hiệu cảnh báo."}]', '[{"phrase":"give a signal"},{"phrase":"warning signal"},{"phrase":"phone signal"},{"phrase":"send a signal"}]', NULL, '/ˈsɪɡnəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/signa/signal__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 3, 'finger', 'ngón tay', 'noun', '[{"en":"She cut her finger while she was chopping vegetables.","vi":"Cô ấy bị đứt tay khi đang thái rau."},{"en":"He wears a silver ring on his little finger.","vi":"Anh ấy đeo một chiếc nhẫn bạc ở ngón út."},{"en":"Please don''t point your finger at people in public.","vi":"Xin đừng chỉ tay vào người khác ở nơi công cộng."}]', '[{"phrase":"little finger"},{"phrase":"point a finger"},{"phrase":"cross your fingers"},{"phrase":"cut your finger"}]', 'ngón cái thường gọi là thumb; ngón chân là toe', '/ˈfɪŋɡər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fin/finge/finger__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 4, 'relevant', 'liên quan; thích hợp', 'adjective', '[{"en":"Please only include information that is relevant to the question.","vi":"Vui lòng chỉ đưa vào những thông tin liên quan đến câu hỏi."},{"en":"Do you have any relevant experience for this job?","vi":"Bạn có kinh nghiệm nào phù hợp với công việc này không?"},{"en":"His advice is still relevant to young people today.","vi":"Lời khuyên của ông ấy vẫn còn phù hợp với giới trẻ ngày nay."}]', '[{"phrase":"relevant information"},{"phrase":"relevant experience"},{"phrase":"relevant to"}]', 'relevant to sth; trái nghĩa: irrelevant', '/ˈreləvənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rel/relev/relevant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 5, 'explore', 'khám phá, thám hiểm; tìm hiểu, xem xét', 'verb', '[{"en":"We spent the afternoon exploring the old part of the city.","vi":"Chúng tôi dành cả buổi chiều khám phá khu phố cổ của thành phố."},{"en":"Children love to explore the world around them.","vi":"Trẻ em thích khám phá thế giới xung quanh."},{"en":"The team is exploring new ways to save money.","vi":"Nhóm đang tìm hiểu những cách mới để tiết kiệm tiền."}]', '[{"phrase":"explore the area"},{"phrase":"explore ways"},{"phrase":"explore the possibility"},{"phrase":"explore options"}]', NULL, '/ɪkˈsplɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/explo/explore__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 6, 'leadership', 'sự lãnh đạo; khả năng lãnh đạo', 'noun', '[{"en":"Under her leadership, the company grew very quickly.","vi":"Dưới sự lãnh đạo của bà ấy, công ty phát triển rất nhanh."},{"en":"He showed strong leadership during the difficult months.","vi":"Anh ấy đã thể hiện khả năng lãnh đạo mạnh mẽ trong những tháng khó khăn."},{"en":"Our school offers a leadership course for older students.","vi":"Trường chúng tôi có một khóa học kỹ năng lãnh đạo cho học sinh lớn."}]', '[{"phrase":"strong leadership"},{"phrase":"leadership skills"},{"phrase":"under the leadership of"},{"phrase":"show leadership"}]', NULL, '/ˈliːdərʃɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/leade/leadership__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 7, 'commitment', 'sự cam kết, tận tâm; nghĩa vụ, việc phải làm', 'noun', '[{"en":"Learning a language takes time and real commitment.","vi":"Học một ngôn ngữ cần thời gian và sự quyết tâm thực sự."},{"en":"The company made a commitment to reduce its waste.","vi":"Công ty đã cam kết giảm lượng rác thải của mình."},{"en":"I can''t join you tonight because of family commitments.","vi":"Tối nay tôi không đi cùng bạn được vì có việc gia đình."}]', '[{"phrase":"make a commitment"},{"phrase":"strong commitment"},{"phrase":"commitment to"},{"phrase":"family commitments"}]', 'commitment to sth / to doing sth', '/kəˈmɪtmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/commi/commitment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 8, 'wake', 'thức dậy; đánh thức', 'verb', '[{"en":"I usually wake up at six o''clock on weekdays.","vi":"Ngày thường tôi hay thức dậy lúc sáu giờ."},{"en":"Please be quiet or you''ll wake the baby.","vi":"Làm ơn giữ yên lặng, không thì bạn sẽ đánh thức em bé đấy."},{"en":"She woke early and went for a walk by the river.","vi":"Cô ấy dậy sớm và đi dạo bên bờ sông."}]', '[{"phrase":"wake up"},{"phrase":"wake up early"},{"phrase":"wake the baby"}]', 'wake – woke – woken', '/weɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wak/wake_/wake__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 9, 'necessarily', 'nhất thiết, tất yếu', 'adverb', '[{"en":"Expensive food is not necessarily better than cheap food.","vi":"Đồ ăn đắt tiền chưa chắc đã ngon hơn đồ ăn rẻ."},{"en":"You don''t necessarily need a car to live here.","vi":"Sống ở đây bạn không nhất thiết phải có ô tô."},{"en":"A good student doesn''t necessarily become a good teacher.","vi":"Một học sinh giỏi không nhất thiết sẽ trở thành một giáo viên giỏi."}]', '[{"phrase":"not necessarily"},{"phrase":"doesn''t necessarily mean"}]', 'thường dùng với phủ định: not necessarily = chưa chắc, không hẳn', '/ˌnesəˈserəli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/nec/neces/necessarily__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 10, 'bright', 'sáng, chói; tươi (màu); thông minh', 'adjective', '[{"en":"The sun was so bright that I had to close my eyes.","vi":"Mặt trời chói đến mức tôi phải nhắm mắt lại."},{"en":"She painted her bedroom a bright yellow color.","vi":"Cô ấy sơn phòng ngủ màu vàng tươi."},{"en":"He''s a bright student who learns things very quickly.","vi":"Cậu ấy là một học sinh thông minh, học gì cũng rất nhanh."}]', '[{"phrase":"bright light"},{"phrase":"bright colors"},{"phrase":"bright student"},{"phrase":"bright future"}]', NULL, '/braɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bri/brigh/bright_1_us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 11, 'frame', 'khung; gọng (kính)', 'noun', '[{"en":"I bought a wooden frame for our wedding photo.","vi":"Tôi đã mua một chiếc khung gỗ cho tấm ảnh cưới của chúng tôi."},{"en":"The window frame is old and needs to be painted.","vi":"Khung cửa sổ đã cũ và cần được sơn lại."},{"en":"He chose glasses with thin black frames.","vi":"Anh ấy chọn một cặp kính gọng đen mảnh."}]', '[{"phrase":"picture frame"},{"phrase":"window frame"},{"phrase":"door frame"},{"phrase":"metal frame"}]', NULL, '/freɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fra/frame/frame__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 12, 'slowly', 'chậm, chậm rãi; dần dần', 'adverb', '[{"en":"Could you speak more slowly, please? I don''t understand.","vi":"Bạn nói chậm hơn được không? Tôi không hiểu."},{"en":"The old man walked slowly down the street.","vi":"Ông cụ chậm rãi đi xuống phố."},{"en":"My English is slowly getting better every month.","vi":"Tiếng Anh của tôi đang dần dần khá lên mỗi tháng."}]', '[{"phrase":"walk slowly"},{"phrase":"speak slowly"},{"phrase":"move slowly"},{"phrase":"slowly but surely"}]', NULL, '/ˈsləʊli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/slo/slowl/slowly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 13, 'bond', 'mối quan hệ gắn bó; trái phiếu', 'noun', '[{"en":"There is a strong bond between the two sisters.","vi":"Hai chị em có mối gắn bó rất bền chặt."},{"en":"Playing sports together helped build a bond within the team.","vi":"Cùng chơi thể thao đã giúp gắn kết cả đội."},{"en":"Some people prefer to invest their savings in government bonds.","vi":"Một số người thích đầu tư tiền tiết kiệm vào trái phiếu chính phủ."}]', '[{"phrase":"strong bond"},{"phrase":"close bond"},{"phrase":"bond between"},{"phrase":"government bonds"}]', NULL, '/bɑːnd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bon/bond_/bond__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 14, 'hire', 'thuê, tuyển (người)', 'verb', '[{"en":"The restaurant is hiring new staff for the summer.","vi":"Nhà hàng đang tuyển thêm nhân viên cho mùa hè."},{"en":"We hired a guide to show us around the mountains.","vi":"Chúng tôi thuê một hướng dẫn viên dẫn đi tham quan vùng núi."},{"en":"They hired a lawyer to help them buy the house.","vi":"Họ thuê một luật sư để giúp họ mua căn nhà."}]', '[{"phrase":"hire staff"},{"phrase":"hire a lawyer"},{"phrase":"hire new employees"}]', 'Anh: hire a car · Mỹ: rent a car', '/ˈhaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hir/hire_/hire__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 15, 'hole', 'lỗ, hố', 'noun', '[{"en":"There''s a big hole in my sock.","vi":"Chiếc tất của tôi bị thủng một lỗ to."},{"en":"The dog dug a hole in the garden to hide its bone.","vi":"Con chó đào một cái hố trong vườn để giấu khúc xương."},{"en":"Be careful, there are lots of holes in this road.","vi":"Cẩn thận nhé, con đường này có nhiều ổ gà lắm."}]', '[{"phrase":"dig a hole"},{"phrase":"a hole in"},{"phrase":"big hole"},{"phrase":"small hole"}]', NULL, '/həʊl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hol/hole_/hole__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 16, 'tie', 'buộc, thắt; hòa (trận đấu)', 'verb', '[{"en":"Can you help me tie my shoes, Dad?","vi":"Bố giúp con buộc dây giày được không ạ?"},{"en":"She tied her hair back before she started cooking.","vi":"Cô ấy buộc tóc ra sau trước khi bắt đầu nấu ăn."},{"en":"Our team tied with the other school in yesterday''s game.","vi":"Đội chúng tôi hòa với trường kia trong trận đấu hôm qua."}]', '[{"phrase":"tie a knot"},{"phrase":"tie your shoes"},{"phrase":"tie up"},{"phrase":"tie back your hair"}]', 'tie – tied – tied; tying', '/taɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tie/tie__/tie__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 17, 'internal', 'bên trong, nội bộ', 'adjective', '[{"en":"The company is holding an internal meeting this afternoon.","vi":"Chiều nay công ty tổ chức một cuộc họp nội bộ."},{"en":"After the accident, doctors checked him for internal injuries.","vi":"Sau tai nạn, các bác sĩ kiểm tra xem anh ấy có bị chấn thương bên trong không."},{"en":"This report is for internal use only.","vi":"Báo cáo này chỉ dùng trong nội bộ."}]', '[{"phrase":"internal meeting"},{"phrase":"internal injuries"},{"phrase":"internal affairs"},{"phrase":"for internal use"}]', 'trái nghĩa: external', '/ɪnˈtɜːrnl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/int/inter/internal__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 18, 'chain', 'dây xích, dây chuyền; chuỗi (cửa hàng)', 'noun', '[{"en":"She wore a gold chain around her neck.","vi":"Cô ấy đeo một sợi dây chuyền vàng quanh cổ."},{"en":"I need to fix the chain on my bike.","vi":"Tôi cần sửa lại sợi xích xe đạp."},{"en":"He works for a large chain of hotels in Asia.","vi":"Anh ấy làm việc cho một chuỗi khách sạn lớn ở châu Á."}]', '[{"phrase":"gold chain"},{"phrase":"bike chain"},{"phrase":"chain of stores"},{"phrase":"hotel chain"}]', NULL, '/tʃeɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chain/chain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 19, 'literature', 'văn học; tài liệu (về một chủ đề)', 'noun', '[{"en":"She decided to study English literature at university.","vi":"Cô ấy quyết định học văn học Anh ở trường đại học."},{"en":"Reading classic literature can improve your vocabulary a lot.","vi":"Đọc văn học kinh điển có thể giúp bạn cải thiện vốn từ rất nhiều."},{"en":"The doctor gave me some literature about healthy eating.","vi":"Bác sĩ đưa cho tôi vài tài liệu về chế độ ăn uống lành mạnh."}]', '[{"phrase":"English literature"},{"phrase":"classic literature"},{"phrase":"modern literature"},{"phrase":"study literature"}]', 'không đếm được', '/ˈlɪtrətʃər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lit/liter/literature__us_7.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 20, 'victim', 'nạn nhân', 'noun', '[{"en":"The victims of the flood received food and clean water.","vi":"Các nạn nhân của trận lũ đã được nhận thức ăn và nước sạch."},{"en":"He was the victim of an online scam last year.","vi":"Năm ngoái anh ấy là nạn nhân của một vụ lừa đảo trên mạng."},{"en":"Don''t let yourself become a victim of bad habits.","vi":"Đừng để bản thân trở thành nạn nhân của những thói quen xấu."}]', '[{"phrase":"victim of"},{"phrase":"become a victim"},{"phrase":"fall victim to"},{"phrase":"flood victims"}]', NULL, '/ˈvɪktɪm/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vic/victi/victim__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 21, 'threaten', 'đe dọa; có nguy cơ', 'verb', '[{"en":"The boss threatened to fire him if he was late again.","vi":"Sếp dọa sẽ đuổi việc anh ta nếu còn đi muộn lần nữa."},{"en":"Pollution threatens the health of people living near the factory.","vi":"Ô nhiễm đe dọa sức khỏe của người dân sống gần nhà máy."},{"en":"The heavy rain threatened to ruin our weekend plans.","vi":"Cơn mưa lớn có nguy cơ phá hỏng kế hoạch cuối tuần của chúng tôi."}]', '[{"phrase":"threaten to"},{"phrase":"threaten someone"},{"phrase":"threaten the future"}]', 'threaten to do sth', '/ˈθretn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/thr/threa/threaten__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 22, 'division', 'sự phân chia; phòng, ban, bộ phận; phép chia', 'noun', '[{"en":"She works in the sales division of a large company.","vi":"Cô ấy làm việc ở bộ phận kinh doanh của một công ty lớn."},{"en":"There was an unfair division of work in our group.","vi":"Việc phân chia công việc trong nhóm chúng tôi không công bằng."},{"en":"My son is learning multiplication and division at school.","vi":"Con trai tôi đang học phép nhân và phép chia ở trường."}]', '[{"phrase":"sales division"},{"phrase":"division of labor"},{"phrase":"division between"},{"phrase":"multiplication and division"}]', NULL, '/dɪˈvɪʒn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/div/divis/division__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 23, 'secure', 'an toàn; chắc chắn, ổn định', 'adjective', '[{"en":"Keep your passport in a secure place when you travel.","vi":"Hãy cất hộ chiếu ở nơi an toàn khi đi du lịch."},{"en":"Children need to feel safe and secure at home.","vi":"Trẻ em cần cảm thấy an toàn và yên tâm khi ở nhà."},{"en":"He left his secure job to start his own business.","vi":"Anh ấy bỏ công việc ổn định để tự mở công ty riêng."}]', '[{"phrase":"secure place"},{"phrase":"secure job"},{"phrase":"feel secure"},{"phrase":"secure password"}]', NULL, '/sɪˈkjʊr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sec/secur/secure__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 24, 'amaze', 'làm kinh ngạc, làm sửng sốt', 'verb', '[{"en":"It amazes me how fast children learn new languages.","vi":"Tôi thấy kinh ngạc khi trẻ em học ngôn ngữ mới nhanh đến vậy."},{"en":"The view from the top of the mountain amazed us.","vi":"Quang cảnh từ trên đỉnh núi khiến chúng tôi sửng sốt."},{"en":"Her piano playing never fails to amaze her teachers.","vi":"Tiếng đàn piano của cô ấy lúc nào cũng khiến các thầy cô kinh ngạc."}]', '[{"phrase":"never fails to amaze"},{"phrase":"be amazed at"},{"phrase":"be amazed by"},{"phrase":"amaze everyone"}]', 'amazed (cảm thấy kinh ngạc) ≠ amazing (tuyệt vời, đáng kinh ngạc)', '/əˈmeɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ama/amaze/amaze__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 25, 'device', 'thiết bị, dụng cụ', 'noun', '[{"en":"Please turn off all electronic devices during the flight.","vi":"Vui lòng tắt tất cả thiết bị điện tử trong suốt chuyến bay."},{"en":"You can watch the course videos on any device.","vi":"Bạn có thể xem video bài học trên bất kỳ thiết bị nào."},{"en":"This small device measures how many steps you take.","vi":"Thiết bị nhỏ này đo số bước chân bạn đi."}]', '[{"phrase":"electronic device"},{"phrase":"mobile device"},{"phrase":"safety device"}]', 'device (n) ≠ devise (v: nghĩ ra)', '/dɪˈvaɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dev/devic/device__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 26, 'birth', 'sự ra đời, sự sinh đẻ', 'noun', '[{"en":"Please write your name and date of birth on the form.","vi":"Vui lòng ghi họ tên và ngày sinh vào mẫu đơn."},{"en":"My sister gave birth to a healthy baby boy last night.","vi":"Tối qua chị tôi đã sinh một bé trai khỏe mạnh."},{"en":"They moved to the city soon after the birth of their daughter.","vi":"Họ chuyển lên thành phố ngay sau khi con gái chào đời."}]', '[{"phrase":"give birth to"},{"phrase":"date of birth"},{"phrase":"place of birth"},{"phrase":"birth of a baby"}]', NULL, '/bɜːrθ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bir/birth/birth__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 27, 'forest', 'rừng', 'noun', '[{"en":"We got lost while walking through the forest.","vi":"Chúng tôi bị lạc khi đi bộ xuyên qua khu rừng."},{"en":"Many animals lose their homes when forests are cut down.","vi":"Nhiều loài động vật mất nơi sống khi rừng bị chặt phá."},{"en":"There is a small forest behind my grandparents'' village.","vi":"Có một khu rừng nhỏ phía sau làng của ông bà tôi."}]', '[{"phrase":"tropical forest"},{"phrase":"dense forest"},{"phrase":"forest fire"},{"phrase":"in the forest"}]', NULL, '/ˈfɔːrɪst/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/for/fores/forest__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 28, 'label', 'nhãn, nhãn mác', 'noun', '[{"en":"Always read the label before you take any medicine.","vi":"Hãy luôn đọc nhãn trước khi uống bất kỳ loại thuốc nào."},{"en":"I put a label with my name on my lunch box.","vi":"Tôi dán một cái nhãn ghi tên mình lên hộp cơm."},{"en":"The label says this shirt should be washed in cold water.","vi":"Nhãn ghi chiếc áo này nên được giặt bằng nước lạnh."}]', '[{"phrase":"read the label"},{"phrase":"price label"},{"phrase":"food label"},{"phrase":"put a label on"}]', NULL, '/ˈleɪbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lab/label/label__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 29, 'root', 'rễ (cây); gốc rễ, nguồn gốc', 'noun', '[{"en":"The roots of this old tree go deep into the ground.","vi":"Rễ của cây cổ thụ này ăn sâu xuống lòng đất."},{"en":"We need to find the root of the problem first.","vi":"Trước tiên chúng ta cần tìm ra gốc rễ của vấn đề."},{"en":"Although he lives abroad, he has never forgotten his roots.","vi":"Dù sống ở nước ngoài, anh ấy chưa bao giờ quên cội nguồn của mình."}]', '[{"phrase":"root of the problem"},{"phrase":"tree roots"},{"phrase":"the root cause"},{"phrase":"take root"}]', NULL, '/ruːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/roo/root_/root__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-4-01', 30, 'factory', 'nhà máy, xí nghiệp', 'noun', '[{"en":"My father has worked in a car factory for twenty years.","vi":"Bố tôi đã làm việc ở một nhà máy ô tô được hai mươi năm."},{"en":"The new factory will create hundreds of jobs for local people.","vi":"Nhà máy mới sẽ tạo ra hàng trăm việc làm cho người dân địa phương."},{"en":"Most of these shoes are made in factories overseas.","vi":"Phần lớn những đôi giày này được sản xuất tại các nhà máy ở nước ngoài."}]', '[{"phrase":"factory worker"},{"phrase":"car factory"},{"phrase":"work in a factory"},{"phrase":"build a factory"}]', NULL, '/ˈfæktri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fac/facto/factory__us_1_rr.mp3', NULL, NULL);
